{"content":[{"type":"text","text":"{
  "profile": {
    "server": "https://agent.robinhood.com/mcp/trading",
    "tools": {
      "cancel_equity_order": {
        "category": "order.cancel",
        "contract": {
          "name": "cancel_equity_order",
          "title": null,
          "description": "Cancel an open equity order by order_id. Always confirm with the user before calling. Resolve order_id via get_equity_orders if the user refers to it by symbol or description; pass the same account_number. Requires an agentic_allowed=true account; non-agentic accounts are rejected — do not call. Cancellation may be rejected if the order has already filled, was already cancelled, or is otherwise ineligible.",
          "input_schema": {
            "type": "object",
            "properties": {
              "account_number": {
                "type": "string",
                "description": "Brokerage account that owns the order. Must come from the user or be clearly implied — never default from get_accounts. Must be agentic_allowed=true. The upstream rejects mismatches against the order's owning account."
              },
              "order_id": {
                "type": "string",
                "description": "Order UUID from get_equity_orders. Must live in account_number."
              }
            },
            "required": [
              "account_number",
              "order_id"
            ],
            "additionalProperties": false
          },
          "output_schema": {
            "type": "object",
            "properties": {
              "data": {
                "type": "object",
                "properties": {
                  "accepted": {
                    "type": "boolean",
                    "description": "True when the broker accepted the cancel request."
                  }
                },
                "description": "Tool-specific result payload; see the inner properties for fields.",
                "required": [
                  "accepted"
                ],
                "additionalProperties": false
              },
              "guide": {
                "type": "string",
                "description": "accepted=true means the broker accepted the cancel request, NOT that the order is already cancelled (cancellation is asynchronous). For the final state, call get_equity_orders: state 'pending_cancelled' = in flight; 'cancelled' or 'partially_filled_rest_cancelled' = succeeded; any filled state = a fill raced the cancel. Offer to check the final state. On error, the cancel was rejected outright — report verbatim."
              }
            },
            "required": [
              "data",
              "guide"
            ],
            "additionalProperties": false
          },
          "annotations": null,
          "execution": null,
          "shape_hash": "sha256:8e4b1d5784426a585c445bd0e5334ad578d3644309ccbf7cd22e7a4154b9534a",
          "contract_hash": "sha256:4cec6376cc80bbdd72ab93974e005483ae59265e677d7b01fb88c2bea21d9dfe"
        },
        "arguments": {
          "account_number": "{account_id}",
          "order_id": "{order_id}"
        },
        "result": {
          "accepted": "data.accepted"
        },
        "confirmed_contract_hash": "sha256:4cec6376cc80bbdd72ab93974e005483ae59265e677d7b01fb88c2bea21d9dfe",
        "mapping_hash": "sha256:266ad2c115a50e13ba096edb056a1c4534c07efb844b7c44639b1bdde70f51b1",
        "confirmed_at": "2026-09-04T16:48:05.913183Z",
        "confirmed_by": "api",
        "categorizer_version": "model-v1:gpt-5.6-sol",
        "proved_contract_hash": null,
        "proved_mapping_hash": null,
        "proved_at": null,
        "proof": null
      },
      "get_accounts": {
        "category": "read.accounts",
        "contract": {
          "name": "get_accounts",
          "title": null,
          "description": "List the user's brokerage accounts. Each account includes an agentic_allowed field indicating whether it's tradable by you — accounts where it's false are read-only to you. Use this to look up account_number values needed by other tools. Exactly one account is tradable by you; when the user is choosing an account for a trade, use that account directly without asking. Does NOT return reliable buying power — route buying-power questions through get_portfolio.",
          "input_schema": {
            "type": "object",
            "additionalProperties": false
          },
          "output_schema": {
            "type": "object",
            "properties": {
              "data": {
                "type": "object",
                "properties": {
                  "accounts": {
                    "type": [
                      "null",
                      "array"
                    ],
                    "items": {
                      "type": [
                        "null",
                        "object"
                      ],
                      "properties": {
                        "account_number": {
                          "type": "string",
                          "description": "Brokerage account number; pass to any tool that requires account_number. Mask all but the last 4 digits (e.g. '••••1234') when displaying to the user."
                        },
                        "rhs_account_number": {
                          "type": "string",
                          "description": "Numeric brokerage account number — pass this (not account_number) to any nummus-backed tool that asks for an account identifier."
                        },
                        "rhc_account_number": {
                          "type": "string",
                          "description": "Crypto account number for this account (e.g. 'RHC1234567'). Absent when no linked crypto account exists. Mask all but the last 4 digits (e.g. '••••1234') when displaying to the user."
                        },
                        "type": {
                          "type": "string",
                          "description": "'cash', 'margin', or 'limited_margin' — the trading-permissions classification for the brokerage account. 'limited_margin' (instant settlement without full margin leverage) applies to accounts where full margin is unavailable, such as retirement (IRA), managed, and agentic accounts. Crypto accounts are never marginable, so a linked crypto account has no equivalent."
                        },
                        "unsettled_funds": {
                          "type": "string",
                          "description": "Proceeds from recent sales not yet settled (cash accounts settle T+1), in the account's currency. Informational only and may lag live trading — this is NOT a spendable or order-gating figure; buying_power from get_portfolio is authoritative for what can be traded now. A cash-type account with unsettled_funds greater than 0 could trade with those proceeds immediately by upgrading to limited margin. Absent when upstream does not report it — treat as unknown, not zero."
                        },
                        "brokerage_account_type": {
                          "type": "string",
                          "description": "Account type, e.g. 'individual', 'ira_traditional', 'ira_roth', 'ira_traditional_inherited', 'ira_roth_inherited', 'isa_stocks_and_shares'."
                        },
                        "nickname": {
                          "type": "string",
                          "description": "User-set nickname; present alongside account_number when set. Cosmetic only — not an agentic_allowed or agentic-account signal."
                        },
                        "is_default": {
                          "type": "boolean",
                          "description": "True for the user's default account. Surface when choosing among multiple accounts."
                        },
                        "agentic_allowed": {
                          "type": "boolean",
                          "description": "True when this account is accessible to this agent specifically. An account with false may be agentic-enabled but scoped to a different agent type — do not tell the user it is disabled. Sole source of truth for eligibility — never infer it from nickname text. review_*/place_*/cancel_* tools reject accounts where this is false."
                        },
                        "option_level": {
                          "type": "string",
                          "description": "Options approval: 'option_level_2' (long calls/puts, covered calls, cash-secured puts), 'option_level_3' (spreads and complex strategies), or empty/'option_level_0' (not approved)."
                        },
                        "management_type": {
                          "type": "string",
                          "description": "Management classification (e.g. 'managed') when applicable; layered on top of brokerage_account_type rather than replacing it."
                        },
                        "affiliate": {
                          "type": "string",
                          "description": "Affiliate / region code (e.g. 'RHF', 'RHUK', 'RHSG'). Affects feature availability for the account."
                        },
                        "state": {
                          "type": "string",
                          "description": "Account state — 'active' is normal; anything else (deactivated, restricted, etc.) means the account cannot trade normally."
                        },
                        "deactivated": {
                          "type": "boolean",
                          "description": "True when the account is currently deactivated."
                        },
                        "permanently_deactivated": {
                          "type": "boolean",
                          "description": "True when the account is permanently closed (cannot be reactivated)."
                        }
                      },
                      "required": [
                        "account_number",
                        "rhs_account_number",
                        "type",
                        "brokerage_account_type",
                        "is_default",
                        "agentic_allowed",
                        "option_level",
                        "state",
                        "deactivated",
                        "permanently_deactivated"
                      ],
                      "additionalProperties": false
                    },
                    "description": "The user's brokerage accounts. Empty when the user has none."
                  }
                },
                "description": "Tool-specific result payload; see the inner properties for fields.",
                "required": [
                  "accounts"
                ],
                "additionalProperties": false
              },
              "guide": {
                "type": "string",
                "description": "Sort the list deterministically when presenting: the default account first, agentic accounts (agentic_allowed=true) second, then other individual accounts, then retirement (IRA) accounts. Present account_number, rhc_account_number (label it \"Crypto Account\"), brokerage_account_type (label it \"Account Type\" — a linked crypto account always shares it, so never add a separate crypto account type column), type (label it \"Brokerage Trading Type\"), nickname (if set), and is_default — in that column order. In the Crypto Account column show \"N/A\" for accounts with an empty rhc_account_number; omit the column entirely only when no account has one. When referring to the account in user-facing prose (e.g. \"your <X> account\"), use nickname when set; fall back to brokerage_account_type otherwise. When displaying account_number or rhc_account_number to the user, mask all but the last 4 digits (e.g. '••••1234'); pass the full value to other tools unchanged — including get_option_level_upgrade_info and any fallback upgrade URL; masking breaks the link. Flag agentic_allowed when the user is choosing an account for a trade. There is exactly one agentic_allowed=true account — use it directly rather than asking which account to trade. agentic_allowed is caller-relative — true means accessible to this agent, false means this agent cannot act on it (the account may still be agentic-enabled for a different agent). Never state agentic_allowed's field name or raw boolean value to the user. Do not use nickname to determine agentic-account eligibility. Skip false accounts for trade operations; if the user asks why, say the account is not accessible to this agent, not that it needs to be enabled. When option_level is empty or 'option_level_0' and the user wants options, call get_option_level_upgrade_info with the account_number; if that tool is unavailable, direct the user to https://applink.robinhood.com/upgrade_options?account_number=<that account's account_number> (embed the full unmasked account_number in the URL). management_type='managed' is layered on brokerage_account_type — surface alongside, not as a replacement. For tools that ask for an account identifier on a crypto-backed flow (get_crypto_positions, future crypto write tools), pass rhs_account_number; for everything else (equities, options, etc.) pass account_number. Do not add an unsettled_funds column to the account table — surface it only via the following rule. Whenever you report an account's funds, value, or buying power and that account has type='cash' with unsettled_funds greater than 0, tell the user those unsettled proceeds could be traded immediately with a limited-margin upgrade, and — if the get_limited_margin_upgrade_info tool is available — call it with the account_number and share the appropriate upgrade link. If that tool is not available, say nothing about limited margin (there is no fallback). "
              }
            },
            "required": [
              "data",
              "guide"
            ],
            "additionalProperties": false
          },
          "annotations": {
            "readOnlyHint": true
          },
          "execution": null,
          "shape_hash": "sha256:21afbfff7211747f1551362a6a8806f9e4b76e2d5537fefd71b97d0129342cb3",
          "contract_hash": "sha256:55b99129976daab68eb463dbd56eacadea781fb14b3fac03afdb8111d0868e6f"
        },
        "arguments": {},
        "result": {
          "items": "data.accounts",
          "account": "account_number",
          "eligible": "agentic_allowed",
          "kind": "brokerage_account_type"
        },
        "confirmed_contract_hash": "sha256:55b99129976daab68eb463dbd56eacadea781fb14b3fac03afdb8111d0868e6f",
        "mapping_hash": "sha256:75f5311a05f730acbfa6e8d8388ccb5fe5dbd32a3dfa2de1bd2172913bebbbb8",
        "confirmed_at": "2026-09-04T16:19:56.343899Z",
        "confirmed_by": "api",
        "categorizer_version": "model-v1:gpt-5.6-sol",
        "proved_contract_hash": "sha256:55b99129976daab68eb463dbd56eacadea781fb14b3fac03afdb8111d0868e6f",
        "proved_mapping_hash": "sha256:75f5311a05f730acbfa6e8d8388ccb5fe5dbd32a3dfa2de1bd2172913bebbbb8",
        "proved_at": "2026-09-04T17:15:55.020780Z",
        "proof": {
          "success": true,
          "resolved": [
            "account",
            "eligible",
            "items",
            "kind"
          ],
          "unresolved": {},
          "detail": "all confirmed result paths resolved with expected types, timezone-aware timestamps, cardinality, and configured-account scope"
        }
      },
      "get_equity_historicals": {
        "category": "read.history",
        "contract": {
          "name": "get_equity_historicals",
          "title": null,
          "description": "Get OHLCV bars for one or more equity symbols across an explicit time range. Use this for charting, \"recent activity\" questions, and backtesting. The server auto-selects an interval when one is not provided. If the bar's interpolated field is true, bar was synthesized to fill a gap and carry no new information.\n\nParameter rules:\n- interval is optional; when omitted, the server auto-selects an interval that targets ~2,500 bars across the requested range. Provide an explicit interval only when you need a specific granularity.\n- interval values are fixed; the server does NOT aggregate intermediate bars. For a custom interval (e.g. 3-minute), request the next-finer fixed interval and aggregate client-side.\n- bounds defaults to 'regular' (RTH only). Use 'extended' or '24_5' only when the user explicitly asks about extended-hours activity.\n- adjustment_type defaults to 'split' (split-adjusted, the right default for backtesting). Use 'none' for raw prices, 'all' for split + dividend adjustment.\n- If the range would produce more bars than the upstream allows at the explicitly requested interval, narrow the range or coarsen the interval — the call is rejected before reaching upstream. The cap does not apply when interval is auto-selected.",
          "input_schema": {
            "type": "object",
            "properties": {
              "symbols": {
                "type": [
                  "null",
                  "array"
                ],
                "items": {
                  "type": "string"
                },
                "description": "One or more stock symbols (uppercase). Up to 10 per call."
              },
              "start_time": {
                "type": "string",
                "description": "Start of the range (RFC3339 UTC, e.g. '2026-01-01T00:00:00Z'). Required."
              },
              "end_time": {
                "type": "string",
                "description": "End of the range (RFC3339 UTC). Optional — when omitted, defaults to the current time."
              },
              "interval": {
                "type": "string",
                "description": "Bar interval. Optional — when omitted, the server picks an interval that targets ~2,500 bars across the requested range. Intraday: 15second, 30second, minute, 5minute, 10minute, 30minute, hour, 4hour. Interday: day, week, month, 3month, 6month, year, 5year, 10year, 20year, 50year. Note: the 1-minute bar is named 'minute' (not '1minute')."
              },
              "bounds": {
                "type": "string",
                "description": "Session bounds. One of 'regular' (RTH, default), 'extended', 'trading', '24_5', '24_7', 'hyper_trading'."
              },
              "adjustment_type": {
                "type": "string",
                "description": "Corporate-action adjustment: 'none' (raw prices), 'split' (default; right for backtesting), or 'all' (split + dividend; intraday only)."
              }
            },
            "required": [
              "symbols",
              "start_time"
            ],
            "additionalProperties": false
          },
          "output_schema": {
            "type": "object",
            "properties": {
              "data": {
                "type": "object",
                "properties": {
                  "results": {
                    "type": [
                      "null",
                      "array"
                    ],
                    "items": {
                      "type": "object",
                      "properties": {
                        "symbol": {
                          "type": "string",
                          "description": "Ticker symbol."
                        },
                        "interval": {
                          "type": "string",
                          "description": "Bar interval. Echoes the request when one was supplied; otherwise reports the server-auto-selected interval."
                        },
                        "bounds": {
                          "type": "string",
                          "description": "Session bounds echoed from the request."
                        },
                        "bars": {
                          "type": [
                            "null",
                            "array"
                          ],
                          "items": {
                            "type": [
                              "null",
                              "object"
                            ],
                            "properties": {
                              "begins_at": {
                                "type": "string",
                                "description": "Start of the bar (RFC3339 UTC). Bars are left-edge labeled."
                              },
                              "open_price": {
                                "type": "string",
                                "description": "First trade price in the bar."
                              },
                              "close_price": {
                                "type": "string",
                                "description": "Last trade price in the bar. NOT the official settled close; for that use get_equity_quotes closes[]."
                              },
                              "high_price": {
                                "type": "string",
                                "description": "Highest trade price in the bar."
                              },
                              "low_price": {
                                "type": "string",
                                "description": "Lowest trade price in the bar."
                              },
                              "volume": {
                                "type": "integer",
                                "description": "Share volume in the bar. Zero for interpolated bars."
                              },
                              "session": {
                                "type": "string",
                                "description": "Wire-format session: 'reg' (regular hours), 'pre' (pre-market), or 'post' (after-hours). Empty/absent when the bar's session is unknown."
                              },
                              "interpolated": {
                                "type": "boolean",
                                "description": "True when the bar was synthesized to fill a gap (no trades occurred). OHLC values are forward-filled from a nearby bar; volume is zero."
                              }
                            },
                            "required": [
                              "begins_at",
                              "open_price",
                              "close_price",
                              "high_price",
                              "low_price",
                              "volume"
                            ],
                            "additionalProperties": false
                          },
                          "description": "Bars in ascending time order. Empty if no trading activity in the window."
                        }
                      },
                      "required": [
                        "symbol",
                        "interval",
                        "bounds",
                        "bars"
                      ],
                      "additionalProperties": false
                    },
                    "description": "One entry per requested symbol that resolved upstream."
                  },
                  "not_found": {
                    "type": [
                      "null",
                      "array"
                    ],
                    "items": {
                      "type": "string"
                    },
                    "description": "Requested symbols that did not resolve (delisted, invalid, or non-equity). Absent when every requested symbol resolved."
                  }
                },
                "description": "Tool-specific result payload; see the inner properties for fields.",
                "required": [
                  "results"
                ],
                "additionalProperties": false
              },
              "guide": {
                "type": "string",
                "description": "Bars are left-edge labeled in UTC; convert to the user's timezone for presentation. Treat interpolated=true bars as gap-fill — they carry no new info and should usually be hidden in charts and ignored for analytics. close_price on the most recent bar is NOT the official settled close — use get_equity_quotes for that. For a multi-bar move, compute return from the first bar's open_price to the last bar's close_price; do not aggregate intermediate interpolated bars. When bounds='regular' the bar series covers only regular trading hours — gaps between trading sessions are not zero-filled, they are simply absent. When the request omitted interval, the 'interval' field on each result reports what the server auto-selected."
              }
            },
            "required": [
              "data",
              "guide"
            ],
            "additionalProperties": false
          },
          "annotations": {
            "readOnlyHint": true
          },
          "execution": null,
          "shape_hash": "sha256:9ababceb32decc3667ba5c3f9a2678a269f0afd142e91bd356eb2f9e9efbbcf9",
          "contract_hash": "sha256:340962a29cb0089ca01ecde8a61950248d46bc7fa0b5f7b7328a4bd6028b5f64"
        },
        "arguments": {
          "symbols": [
            "{symbol}"
          ],
          "start_time": "{start_time}",
          "end_time": "{end_time}",
          "interval": "{interval}"
        },
        "result": {
          "items": "data.results.0.bars",
          "timestamp": "begins_at",
          "open": "open_price",
          "high": "high_price",
          "low": "low_price",
          "close": "close_price",
          "volume": "volume"
        },
        "confirmed_contract_hash": "sha256:340962a29cb0089ca01ecde8a61950248d46bc7fa0b5f7b7328a4bd6028b5f64",
        "mapping_hash": "sha256:8ac04823f3f93f0f9d5b0b9b681ba84d0c2478431a7e286c25c73f1f400d9f9e",
        "confirmed_at": "2026-09-04T16:48:14.113387Z",
        "confirmed_by": "api",
        "categorizer_version": "model-v1:gpt-5.6-sol",
        "proved_contract_hash": "sha256:340962a29cb0089ca01ecde8a61950248d46bc7fa0b5f7b7328a4bd6028b5f64",
        "proved_mapping_hash": "sha256:8ac04823f3f93f0f9d5b0b9b681ba84d0c2478431a7e286c25c73f1f400d9f9e",
        "proved_at": "2026-09-04T17:15:55.020780Z",
        "proof": {
          "success": false,
          "resolved": [],
          "unresolved": {
            "needs": "start_time, symbol"
          },
          "detail": "this tool needs probe values for: start_time, symbol. Supply them and prove again."
        }
      },
      "get_equity_orders": {
        "category": "read.orders",
        "contract": {
          "name": "get_equity_orders",
          "title": null,
          "description": "Fetch equity orders for an account — list mode (newest first; open and closed, including fills, cancellations, rejections) or single-order mode by passing order_id. When the user asks for \"orders\" without specifying an asset class, call get_equity_orders, get_option_orders, and get_advanced_orders (OCO / multi-leg contingency orders) in parallel.\n\nFiltering tips:\n- Prefer narrow queries: combine state, symbol, and/or created_at_gte for specific questions (e.g. \"my filled AAPL orders this week\") — the per-page cap is fixed.\n- created_at_gte: interpret relative times in the user's timezone, convert to UTC before sending.\n- symbol forces a symbol→instrument lookup; omit it if you don't need it.",
          "input_schema": {
            "type": "object",
            "properties": {
              "account_number": {
                "type": "string",
                "description": "Brokerage account number. Must come from the user or be clearly implied — never default from get_accounts."
              },
              "order_id": {
                "type": "string",
                "description": "Filter to a single order by UUID. The response shape is unchanged (orders[] with at most one entry); empty when the order does not belong to account_number."
              },
              "state": {
                "type": "string",
                "description": "Filter by single state: new, queued, confirmed, unconfirmed, partially_filled, filled, cancelled, rejected, failed, voided."
              },
              "symbol": {
                "type": "string",
                "description": "Filter to one symbol (triggers a symbol→instrument lookup before the orders call)."
              },
              "created_at_gte": {
                "type": "string",
                "description": "Lower bound (inclusive). ISO 8601 UTC or YYYY-MM-DD; naive values are interpreted as UTC."
              },
              "placed_agent": {
                "type": "string",
                "description": "Filter to one source: 'user', 'agentic' (MCP), 'recurring', 'drip', etc."
              },
              "cursor": {
                "type": "string",
                "description": "Pagination cursor. Omit for the first page; for the next page, pass the cursor query param from the prior response's next URL."
              }
            },
            "required": [
              "account_number"
            ],
            "additionalProperties": false
          },
          "output_schema": {
            "type": "object",
            "properties": {
              "data": {
                "type": "object",
                "properties": {
                  "orders": {
                    "type": [
                      "null",
                      "array"
                    ],
                    "items": {
                      "type": [
                        "null",
                        "object"
                      ],
                      "properties": {
                        "id": {
                          "type": "string",
                          "description": "Order UUID; needed by cancel_equity_order."
                        },
                        "instrument_id": {
                          "type": "string",
                          "description": "Instrument UUID; resolve to symbol via the instruments endpoint if needed."
                        },
                        "symbol": {
                          "type": "string",
                          "description": "Ticker symbol."
                        },
                        "side": {
                          "type": "string",
                          "description": "'buy' or 'sell'."
                        },
                        "type": {
                          "type": "string",
                          "description": "Upstream type: 'market' or 'limit'. Combine with trigger to recover the user-facing market/limit/stop_market/stop_limit."
                        },
                        "state": {
                          "type": "string",
                          "description": "Lifecycle state: new, queued, unconfirmed, partially_filled, filled, cancelled, rejected, failed, voided, pending_cancelled, partially_filled_rest_cancelled, and (for short-sale orders) locating, locate_failed."
                        },
                        "quantity": {
                          "type": [
                            "null",
                            "string"
                          ],
                          "description": "Originally-requested share quantity. Null for dollar-based orders before the first fill."
                        },
                        "cumulative_quantity": {
                          "type": "string",
                          "description": "Shares filled so far. Less than quantity while partially filled; equal once filled."
                        },
                        "price": {
                          "type": [
                            "null",
                            "string"
                          ],
                          "description": "Limit price for limit/stop_limit orders; null for market orders."
                        },
                        "stop_price": {
                          "type": [
                            "null",
