      "exercise_option": {
        "contract": {
          "name": "exercise_option",
          "title": null,
          "description": "Exercise a long options position — a call exercises the right to buy the underlying shares at the strike price; a put exercises the right to sell. Exercise is irrevocable once state moves past queued.\n\nNever call this tool without asking the user to explicitly confirm the specific exercise first: state the option, quantity, and expected cash impact (debit for calls, credit for puts), then wait for their affirmative reply before calling. The user's original request to exercise is NOT itself sufficient confirmation — a generic \"exercise my calls\" does not confirm a specific option and quantity.\n\nPosition requirements: confirm via get_option_positions that the position type=long and quantity > 0.\n\nAccount requirements: confirm via get_accounts that the chosen account is agentic_allowed=true AND has option_level_2 or option_level_3. If agentic_allowed=false do NOT call. If option_level is empty or option_level_0, do NOT call; follow the get_accounts guide for how to direct the user to enroll.\n\nIndex options cannot be manually exercised and will be rejected. Exercises submitted during market hours execute the same day; requests submitted after market close — including on late-close trading days — are queued for overnight processing.\n\nParameter rules:\n- quantity must be a positive integer and cannot exceed the position's available contracts.\n- allow_shorts=true only applies to PUT exercises where the account does not own enough shares to deliver. Require explicit user confirmation before setting this — it creates a short equity position in the underlying stock.\n- reason is optional but recommended; collect it from the user when they volunteer a motivation.\n- ref_id: use the same UUID on retries of the same logical exercise; use a new UUID for a new exercise.",
          "input_schema": {
            "type": "object",
            "properties": {
              "account_number": {
                "type": "string",
                "description": "Brokerage account number. Must be agentic_allowed=true with option_level_2 or option_level_3."
              },
              "option_id": {
                "type": "string",
                "description": "Option instrument UUID from get_option_positions or get_option_instruments. The position must be type=long."
              },
              "quantity": {
                "type": "integer",
                "description": "Number of contracts to exercise (positive integer, minimum 1)."
              },
              "ref_id": {
                "type": "string",
                "description": "Idempotency key (UUID). Generate once per logical exercise and re-send on retry. Omitting falls back to a server-generated key."
              },
              "reason": {
                "type": "string",
                "description": "Optional exercise reason: covering_early_assignment | buying_stocks | not_enough_liquidity_or_spread_too_wide | hedging_position."
              },
              "allow_shorts": {
                "type": "boolean",
                "description": "When true, allows a PUT exercise to proceed even when the account does not own enough shares to deliver — creating a short equity position. Requires explicit user confirmation that they intend to short the underlying stock. Default false."
              }
            },
            "required": [
              "account_number",
              "option_id",
              "quantity"
            ],
            "additionalProperties": false
          },
          "output_schema": {
            "type": "object",
            "properties": {
              "data": {
                "type": "object",
                "properties": {
                  "event": {
                    "type": [
                      "null",
                      "object"
                    ],
                    "properties": {
                      "id": {
                        "type": "string",
                        "description": "Exercise event UUID."
                      },
                      "state": {
                        "type": "string",
                        "description": "queued (submitted, not yet processed — cancellable via cancel_option_exercise) | confirmed (processing complete, irrevocable) | voided (cancelled) | canceled (cancelled by customer via the cancel endpoint) | reversed (reversed by broker)."
                      },
                      "type": {
                        "type": "string",
                        "description": "exercise (normal) | generic (index options in pending state — index options cannot be manually exercised)."
                      },
                      "quantity": {
                        "type": "string",
                        "description": "Contracts exercised."
                      },
                      "option_id": {
                        "type": "string",
                        "description": "Option instrument UUID."
                      },
                      "chain_id": {
                        "type": "string",
                        "description": "Option chain UUID."
                      },
                      "account_number": {
                        "type": "string",
                        "description": "Brokerage account number. Mask all but the last 4 digits when displaying to the user."
                      },
                      "direction": {
                        "type": "string",
                        "description": "debit = call exercise (cash paid to acquire shares) | credit = put exercise (cash received for delivering shares)."
                      },
                      "total_cash_amount": {
                        "type": "string",
                        "description": "Absolute cash amount of the exercise: strike × multiplier × contracts for calls; net proceeds for puts."
                      },
                      "event_date": {
                        "type": "string",
                        "description": "Settlement date of the exercise (YYYY-MM-DD)."
                      },
                      "ref_id": {
                        "type": [
                          "null",
                          "string"
                        ],
                        "description": "Idempotency key echoed from the request."
                      },
                      "underlying_price": {
                        "type": [
                          "null",
                          "string"
                        ],
                        "description": "Underlying spot price at exercise time. Nil when not yet available."
                      },
                      "created_at": {
                        "type": "string",
                        "description": "ISO 8601 timestamp when the exercise request was created."
                      },
                      "updated_at": {
                        "type": "string",
