      "get_crypto_orders": {
        "contract": {
          "name": "get_crypto_orders",
          "title": null,
          "description": "List crypto order history for an account — newest first. Open and closed orders, including fills, cancellations, and rejections. Pass order_id to retrieve a single order by UUID.\n\nFiltering tips:\n- Prefer narrow queries: combine state (or state_group), symbol, and/or created_at_gte for specific questions.\n- created_at_gte: interpret relative times in the user's timezone, convert to UTC before sending.\n- updated_at_gte: useful when polling for order fills or state transitions.\n- symbol triggers a symbol→currency_pair_id lookup; omit it if you don't need it.\n\nWhen the user asks for \"orders\" without specifying equity, options, or crypto, call get_equity_orders, get_option_orders, and get_crypto_orders in parallel.\n\nFor requests spanning all accounts, re-fetch the account list with get_accounts first — a list from earlier in the conversation may be missing newly created accounts.",
          "input_schema": {
            "type": "object",
            "properties": {
              "rhs_account_number": {
                "type": "string",
                "description": "Numeric brokerage account number (the 'rhs_account_number' field on get_accounts entries — distinct from the alphanumeric 'account_number'). Required."
              },
              "order_id": {
                "type": "string",
                "description": "Filter to a single order by UUID. The response shape is unchanged (results[] with at most one entry); empty when the order does not belong to the account."
              },
              "state": {
                "type": "string",
                "description": "Filter by single state: queued, confirmed, partially_filled, filled, canceled, rejected, failed, voided. For open-vs-closed shortcuts, use state_group instead."
              },
              "state_group": {
                "type": "string",
                "description": "Filter by state group: 'open' or 'closed'. Quick shortcut — 'open' covers queued/confirmed/partially_filled, 'closed' covers filled/canceled/rejected/failed/voided. Mutually exclusive with state."
              },
              "side": {
                "type": "string",
                "description": "Filter by side: 'buy' or 'sell'."
              },
              "symbol": {
                "type": "string",
                "description": "Filter by crypto symbol (e.g. 'BTC', 'ETH', or 'BTC-USD'). Triggers a symbol→currency_pair_id lookup before the orders call."
              },
              "created_at_gte": {
                "type": "string",
                "description": "Lower bound (inclusive) on created_at. ISO 8601 UTC; naive values are interpreted as UTC."
              },
              "updated_at_gte": {
                "type": "string",
                "description": "Lower bound (inclusive) on updated_at. ISO 8601 UTC. Useful for polling for fills — each state transition bumps updated_at."
              },
              "cursor": {
                "type": "string",
                "description": "Pagination cursor. Omit for the first page; for the next page, pass the cursor query param from the prior response's next URL."
              }
            },
            "required": [
              "rhs_account_number"
            ],
            "additionalProperties": false
          },
          "output_schema": {
            "type": "object",
            "properties": {
              "data": {
                "type": "object",
                "properties": {
                  "rhs_account_number": {
                    "type": "string",
                    "description": "Echo of the brokerage account number this page was queried with. Every order in results belongs to this account — when querying multiple accounts in parallel, attribute orders using this echo, not memory of which call was which."
                  },
                  "crypto_account_number": {
                    "type": "string",
                    "description": "Crypto account number (e.g. 'RHC1234567') these orders belong to. Present THIS as the account to the user — not the brokerage account number used to look it up. When absent, refer to the account as the user's linked crypto account."
                  },
                  "results": {
                    "type": [
                      "null",
                      "array"
                    ],
                    "items": {
                      "type": [
                        "null",
                        "object"
                      ],
                      "properties": {
