      "get_crypto_quotes": {
        "contract": {
          "name": "get_crypto_quotes",
          "title": null,
          "description": "Get real-time bid/ask/mark prices plus the previous close for one or more crypto pair symbols (e.g. BTC-USD).",
          "input_schema": {
            "type": "object",
            "properties": {
              "symbols": {
                "type": [
                  "null",
                  "array"
                ],
                "items": {
                  "type": "string"
                },
                "description": "One or more crypto pair symbols (e.g. 'BTC-USD', 'ETH-USD'). Hyphenated and unhyphenated forms are both accepted on input; the response symbol field comes back unhyphenated."
              },
              "timezone": {
                "type": "string",
                "description": "Optional IANA timezone name (e.g. 'America/New_York', 'America/Los_Angeles') that anchors the previous-close (open_price) day boundary to the user's local midnight and sets the timezone the response timestamps (bid_time, ask_time, updated_at) are rendered in. Pass ONLY when the user's timezone is known from context — do NOT guess it, infer it from language, or default it. When omitted, the previous close is anchored to midnight US Eastern and timestamps are rendered in US Eastern. Must be a valid IANA name — not an abbreviation ('PST'), a UTC offset ('-08:00'), or 'Local'."
              },
              "rhs_account_number": {
                "type": "string",
                "description": "Optional numeric brokerage account number (the 'rhs_account_number' from get_accounts). When supplied, bid/ask/mark and the previous close are priced on this account's execution routing — the venues its orders actually fill at — and the applied routing is echoed in routing. When omitted, prices use the caller's own routing (it is set at the user level, so any of their crypto accounts yields the same routing). A caller with no crypto account, or an account that cannot be resolved, receives market-maker-routed pricing."
              }
            },
            "required": [
              "symbols"
            ],
            "additionalProperties": false
          },
          "output_schema": {
            "type": "object",
            "properties": {
              "data": {
                "type": "object",
                "properties": {
                  "results": {
                    "type": [
                      "null",
                      "array"
                    ],
                    "items": {
                      "type": [
                        "null",
                        "object"
                      ],
                      "properties": {
                        "symbol": {
                          "type": "string",
                          "description": "Crypto pair symbol returned by upstream in unhyphenated form (e.g. 'BTCUSD'). To cross-reference with get_currency_pairs.symbol (which is hyphenated, e.g. 'BTC-USD'), strip the hyphen from that field or insert one before the last 3 characters of this one."
                        },
                        "id": {
                          "type": "string",
                          "description": "Currency-pair instrument UUID. Pass in the currency_pair_ids array to add_to_watchlist / remove_from_watchlist — no separate get_currency_pairs call needed just to get the UUID. Also matches get_currency_pairs.id and the currency_pair_id on get_crypto_positions rows."
                        },
                        "bid_price": {
                          "type": "string",
                          "description": "Highest current buy-order price. Zero when the book is closed or unavailable — do NOT present zero as a price."
                        },
                        "bid_time": {
                          "type": [
                            "null",
                            "string"
                          ],
                          "description": "Timestamp of bid_price, rendered in the request timezone (the get_crypto_quotes 'timezone' parameter; US Eastern when not supplied). Present when the upstream included side timestamps; otherwise absent."
                        },
                        "ask_price": {
                          "type": "string",
                          "description": "Lowest current sell-order price. Zero when the book is closed or unavailable."
                        },
                        "ask_time": {
                          "type": [
                            "null",
                            "string"
                          ],
                          "description": "Timestamp of ask_price, rendered in the request timezone (the get_crypto_quotes 'timezone' parameter; US Eastern when not supplied). Present when the upstream included side timestamps; otherwise absent."
                        },
                        "mark_price": {
                          "type": "string",
                          "description": "Reference midpoint computed from bid and ask. Zero when both sides of the book are unavailable."
                        },
                        "open_price": {
                          "type": "string",
                          "description": "Previous close — the reference midpoint (same bid/ask-mid basis as mark_price) at the midnight day boundary of the request timezone (the get_crypto_quotes 'timezone' parameter; US Eastern when not supplied). Crypto trades continuously, so this boundary price is the prior day's close. Resets daily; NOT a last-trade price."
                        },
                        "routing": {
                          "type": "string",
                          "description": "Execution routing these prices are quoted on, matching the routing on get_crypto_orders rows. bid_price, ask_price, mark_price, and open_price are all priced on this routing. Absent when routing information is unavailable."
                        },
                        "updated_at": {
                          "type": "string",
                          "description": "Time this snapshot was last refreshed, rendered in the request timezone (the get_crypto_quotes 'timezone' parameter; US Eastern when not supplied) — the same zone that anchors open_price. Use to judge freshness — when stale, phrase as 'as of <time>' rather than 'current'."
                        }
                      },
                      "required": [
                        "symbol",
                        "id",
                        "bid_price",
                        "ask_price",
                        "mark_price",
                        "open_price",
                        "updated_at"
                      ],
                      "additionalProperties": false
                    },
                    "description": "One entry per requested symbol with live market data. Empty if no symbol resolved."
                  }
                },
                "description": "Tool-specific result payload; see the inner properties for fields.",
                "required": [
                  "results"
                ],
                "additionalProperties": false
              },
              "guide": {
                "type": "string",
                "description": "Current price: prefer mark_price when both sides of the book are populated; if mark_price is zero, fall back to the most recent of bid_time / ask_time and quote the side that updated last. Drop bid or ask when zero — the book is unavailable on that side. Use updated_at to judge freshness; if it is more than a few seconds stale, phrase as \"as of <time>\" rather than \"current\". open_price is the previous close — in continuous crypto the midnight boundary price is the prior day's close. That boundary is midnight in the request timezone (the 'timezone' parameter), or US Eastern when none is supplied; response timestamps carry that same timezone's offset, so quote \"as of\" times in it directly. For change vs the previous close, compute (mark_price - open_price) / open_price. The response symbol comes back unhyphenated (e.g. 'BTCUSD'); the canonical form from get_currency_pairs is hyphenated ('BTC-USD') — strip the hyphen to cross-reference. bid/ask/mark reflect the execution routing reported in routing: the supplied account's routing when rhs_account_number was given, otherwise the caller's user-level routing (market maker routing when the caller has no crypto account). This is informational; place_order routing is selected per account at order time."
              }
            },
            "required": [
              "data",
              "guide"
            ],
            "additionalProperties": false
          },
          "annotations": {
            "readOnlyHint": true
          },
