          "shape_hash": "sha256:c157b25b7fb0376282d1d0ab60d23f961560bcb91b9c3ffb8908b27184f114a3",
          "contract_hash": "sha256:a4bd194107135bdef11a0156a13e4d6a18c13b8950a92c1dad0849577b60287c"
        },
