      "get_index_historicals": {
        "contract": {
          "name": "get_index_historicals",
          "title": null,
          "description": "Get OHLC value bars for one or more market indexes (by instrument UUID) across an explicit time range. Use this for charting an index's history and \"recent movement\" questions. If the bar's interpolated field is true, bar was synthesized to fill a gap and carry no new information.\n\nParameter rules:\n- instrument_ids are index instrument UUIDs from get_indexes. Resolve symbols there first; this tool does not accept ticker symbols.\n- interval is required; pick the coarsest interval that answers the question. If the requested interval would produce too many bars for the range, the call is rejected — narrow the range or coarsen the interval.",
          "input_schema": {
            "type": "object",
            "properties": {
              "instrument_ids": {
                "type": [
                  "null",
                  "array"
                ],
                "items": {
                  "type": "string"
                },
                "description": "Index instrument UUIDs (from get_indexes). Up to 10 per call."
              },
              "start_time": {
                "type": "string",
                "description": "Start of the range (RFC3339 UTC, e.g. '2026-01-01T00:00:00Z'). Required."
              },
              "end_time": {
                "type": "string",
                "description": "End of the range (RFC3339 UTC). Optional — when omitted, defaults to the current time."
              },
              "interval": {
                "type": "string",
                "description": "Bar interval. Required — there is no server auto-select for indexes. Intraday: 5second, 15second, 30second, minute, 5minute, 10minute, 30minute, hour, 4hour. Interday: day, week, month, 3month, 6month, year, 5year, 10year, 20year, 50year. Note: the 1-minute bar is named 'minute' (not '1minute')."
              }
            },
            "required": [
              "instrument_ids",
              "start_time",
              "interval"
            ],
            "additionalProperties": false
          },
          "output_schema": {
            "type": "object",
            "properties": {
              "data": {
                "type": "object",
                "properties": {
                  "results": {
                    "type": [
                      "null",
                      "array"
                    ],
                    "items": {
                      "type": [
                        "null",
                        "object"
                      ],
                      "properties": {
                        "instrument_id": {
                          "type": "string",
                          "description": "UUID of the index instrument."
                        },
                        "symbol": {
                          "type": "string",
                          "description": "Index ticker (e.g. SPX, NDX)."
                        },
                        "interval": {
                          "type": "string",
                          "description": "Bar interval echoed from the request."
                        },
                        "bars": {
                          "type": [
                            "null",
                            "array"
                          ],
                          "items": {
                            "type": [
                              "null",
                              "object"
                            ],
                            "properties": {
                              "begins_at": {
                                "type": "string",
                                "description": "Start of the bar (RFC3339 UTC). Bars are left-edge labeled."
                              },
                              "open_value": {
                                "type": "string",
                                "description": "Index level at the start of the bar, as a decimal string."
                              },
                              "high_value": {
                                "type": "string",
                                "description": "Highest index level in the bar, as a decimal string."
                              },
                              "low_value": {
                                "type": "string",
                                "description": "Lowest index level in the bar, as a decimal string."
                              },
                              "close_value": {
                                "type": "string",
                                "description": "Index level at the end of the bar, as a decimal string. NOT an official close; for the live level use get_index_quotes."
                              },
                              "interpolated": {
                                "type": "boolean",
                                "description": "True when the bar was synthesized to fill a gap (no values were published); its levels are filled from a nearby bar and carry no new information."
                              }
                            },
                            "required": [
                              "begins_at",
                              "open_value",
                              "high_value",
                              "low_value",
                              "close_value"
                            ],
                            "additionalProperties": false
                          },
                          "description": "Bars in ascending time order. May be empty if no values were published in the window."
                        }
                      },
                      "required": [
                        "instrument_id",
                        "symbol",
                        "interval",
                        "bars"
                      ],
                      "additionalProperties": false
                    },
                    "description": "One entry per requested index that resolved upstream. Empty if no instrument_id resolved."
                  },
                  "not_found": {
                    "type": [
                      "null",
                      "array"
                    ],
                    "items": {
                      "type": "string"
                    },
                    "description": "Requested instrument_ids that did not resolve (invalid or unknown). Absent when every requested id resolved."
                  },
                  "restricted": {
                    "type": [
                      "null",
                      "array"
                    ],
                    "items": {
                      "type": [
                        "null",
                        "object"
                      ],
                      "properties": {
                        "instrument_id": {
                          "type": "string",
                          "description": "UUID of the restricted index instrument, as requested."
                        },
                        "symbol": {
                          "type": "string",
                          "description": "Index ticker whose historical data is not licensed for this channel."
