                      },
                      "required": [
                        "instrument_id",
                        "symbol"
                      ],
                      "additionalProperties": false
                    },
                    "description": "Requested indexes whose historical data is not licensed for this channel. No bars are ever returned for these. Absent when none were requested."
                  }
                },
                "description": "Tool-specific result payload; see the inner properties for fields.",
                "required": [
                  "results"
                ],
                "additionalProperties": false
              },
              "guide": {
                "type": "string",
                "description": "Bars are left-edge labeled in UTC; convert to the user's timezone for presentation. Treat interpolated=true bars as gap-fill — they carry no new information and should usually be hidden in charts and ignored for analytics. Bars carry index values, not trade prices — there is no volume. For the current level use get_index_quotes; for a multi-bar move, compute the change from the first bar's open_value to the last bar's close_value. Match results to your request by instrument_id; requested ids that did not resolve are listed in not_found, and ids under restricted are unavailable for licensing reasons — tell the user that rather than retrying."
              }
