                        },
                        "symbol": {
                          "type": "string",
                          "description": "Underlying root symbol, e.g. 'AAPL'."
                        },
                        "interval": {
                          "type": "string",
                          "description": "Bar interval. Echoes the request when one was supplied; otherwise the server-selected value."
                        },
                        "bounds": {
                          "type": "string",
                          "description": "Session bounds echoed from the request."
                        },
                        "bars": {
                          "type": [
                            "null",
                            "array"
                          ],
                          "items": {
                            "type": [
                              "null",
                              "object"
                            ],
                            "properties": {
                              "begins_at": {
                                "type": "string",
                                "description": "Start of the bar (RFC3339 UTC). Bars are left-edge labeled."
                              },
                              "open_price": {
                                "type": "string",
                                "description": "First price in the bar, as a decimal string."
                              },
                              "high_price": {
                                "type": "string",
                                "description": "Highest price in the bar, as a decimal string."
                              },
                              "low_price": {
                                "type": "string",
                                "description": "Lowest price in the bar, as a decimal string."
