s":false},"description":"Items on the user's options watchlist. Empty when the watchlist exists but is empty."},"list_id":{"type":"string","description":"The options watchlist this call resolved to."}},"description":"Tool-specific result payload; see the inner properties for fields.","required":["items","list_id"],"additionalProperties":false},"guide":{"type":"string","description":"Surface name to the user — it is the human-readable position title (e.g. "Long Call AAPL Jan 2026 $200"). option_ids[0] is the contract id to pass to get_option_quotes, review_option_order, place_option_order, or remove_option_from_watchlist. If the user mentions a multi-leg strategy (vertical, iron condor, etc.) they have in their watchlist and you don't see it here, tell them this tool only shows single-leg items and to check the app. "no options watchlist found" in the error means options trading is not enabled for this account."}},"required":["data","guide"],"additionalProperties":false},"annotations":{"readOnlyHint":true},"execution":null,"shape_hash":"sha256:e739774ee43be8ada30c486faa218ca0ad55321dc6aa6f902745a593577e3a03","contract_hash":"sha256:e9184182e09486dcbbd71496874be0c787d9de9b9c456b176fa02bda5fd7b43f"},"category":null,"arguments":{},"result":{},"reason":"Options and watchlists are outside this broker profile’s scope.","warnings":[],"original":{"name":"get_option_watchlist","category":null,"arguments":{},"result":{},"reason":"Options and watchlists are outside this broker profile’s scope.","warnings":[]},"edits":[]},"get_pnl_trade_history":{"contract":{"name":"get_pnl_trade_history","title":null,"description":"Get a customer's per-trade realized profit & loss — a chronological, paginated list of closed/realizing trades (equities, options, crypto, prediction markets) with symbol, side, quantity, price, and realized gain/loss. This is the same data behind the app's PnL hub ("Realized profit & loss"). Read-only. Trades only. Use get_realized_pnl for aggregate/bucketed totals.","input_schema":{"type":"object","properties":{"account_number":{"type":"string","description":"Brokerage account number (the rhs_account_number from get_accounts). Obtain it from get_accounts."},"span":{"type":"string","description":"Preset window: week (default), month, 3month, ytd, or all. Wormhole offers preset spans only (no arbitrary date range)."},"symbol":{"type":"string","description":"Optional single stock symbol filter (trimmed + uppercased). Omit for all symbols; one symbol per call."},"cursor":{"type":"string","description":"Pagination cursor from a previous response's next_cursor. Omit for the first page."}},"required":["account_number"],"additionalProperties":false},"output_schema":{"type":"object","properties":{"data":{"type":"object","properties":{"account_number":{"type":"string","description":"The account the trades are for (echoed)."},"span":{"type":"string","description":"The span window actually used (defaults to week)."},"trades":{"type":["null","array"],"items":{"type":"object","properties":{"timestamp":{"type":"string","description":"RFC3339 time the trade closed (the realizing event)."},"symbol":{"type":"string","description":"Instrument symbol traded."},"side":{"type":"string","description":"'buy' or 'sell'."},"quantity":{"type":"string","description":"Shares/contracts, decimal string."},"price":{"type":"string","description":"Execution (close) price, decimal string."},"realized_gain":{"type":"string","description":"Realized profit/loss on this closing trade, decimal string in the account currency."}},"required":["timestamp","symbol","side","quantity","price","realized_gain"],"additionalProperties":false},"description":"Closed/realizing trades in the window, most-recent-first. Empty when there were none."},"next_cursor":{"type":"string","description":"Pagination cursor for the next page; empty when there are no more trades."}},"description":"Tool-specific result payload; see the inner properties for fields.","required":["account_number","span","trades","next_cursor"],"additionalProperties":false},"guide":{"type":"string","description":"trades are returned most-recent-first. Each entry is a closed/realizing trade with the realized gain/loss on it. price is the execution (close) price. The window is a preset span (not an arbitrary date range); default is the last week. Paginate with cursor: pass next_cursor from the previous response for the next page; an empty next_cursor means there are no more trades. An empty trades list means there were no realized trades in the window — a valid result, not an error. To filter more than one symbol, call once per symbol. Treat figures as informational, not a tax document or tax/performance advice."}},"required":["data","guide"],"additionalProperties":false},"annotations":{"readOnlyHint":true},"execution":null,"shape_hash":"sha256:815943b545543edf3579c2b698e14bf1a51f8489aec3fa429b8a359fd9a8e1d5","contract_hash":"sha256:84ff71612c2ab38cf541f327a3464e9cd6789bcfbb48f6d1e13e6e407d8c9208"},"category":null,"arguments":{},"result":{},"reason":"Realized-profit history has no matching callable category in this profile.","warnings":[],"original":{"name":"get_pnl_trade_history","category":null,"arguments":{},"result":{},"reason":"Realized-profit history has no matching callable category in this profile.","warnings":[]},"edits":[]},"get_popular_watchlists":{"contract":{"name":"get_popular_watchlists","title":null,"description":"Discover Robinhood-curated lists the user can follow (e.g. '100 Most Popular', 'Daily Movers'). Use to find a list_id, then pass it to follow_watchlist.","input_schema":{"type":"object","additionalProperties":false},"output_schema":{"type":"object","properties":{"data":{"type":"object","properties":{"lists":{"type":["null","array"],"items":{"type":["null","object"],"properties":{"id":{"type":"string","description":"List UUID. Pass to follow_watchlist."},"display_name":{"type":"string","description":"Human-readable list name (e.g. '100 Most Popular', 'Daily Movers')."},"item_count":{"type":"integer","description":"Number of items in the list."},"is_badged":{"type":"boolean","description":"True for newly-published curated lists. Worth surfacing as 'new' when listing options for the user to follow."}},"required":["id","display_name","item_count"],"additionalProperties":false},"description":"Robinhood-curated lists available for the user to follow."},"next":{"type":"string","description":"Cursor URL for the next page when more results exist. Absent on the last page."}},"description":"Tool-specific result payload; see the inner properties for fields.","required":["lists"],"additionalProperties":false},"guide":{"type":"string","description":"For 'this list is new' surfacing, use is_badged. The response is paginated — if next is non-null there are more lists; call again with the cursor from next."}},"required":["data","guide"],"additionalProperties":false},"annotations":{"readOnlyHint":true},"execution":null,"shape_hash":"sha256:66f6749da697cdad7aeea97f84d4cb29b7cfae0995a5a72802e51ff18cc90178","contract_hash":"sha256:fa58cb77e1644efac3d9e88cb514bb0a0473ff8186851add648e81051ddd15e5"},"category":null,"arguments":{},"result":{},"reason":"Watchlists are outside this broker profile’s scope.","warnings":[],"original":{"name":"get_popular_watchlists","category":null,"arguments":{},"result":{},"reason":"Watchlists are outside this broker profile’s scope.","warnings":[]},"edits":[]},"get_portfolio":{"contract":{"name":"get_portfolio","title":null,"description":"Get the account's portfolio market value breakdown by asset type and buying power. Use for "how much is my account worth?", "what's my portfolio breakdown?", "how much do I have in options?", and "how much can I spend / afford?" questions.","input_schema":{"type":"object","properties":{"account_number":{"type":"string","description":"Brokerage account number. Obtain from get_accounts."}},"required":["account_number"],"additionalProperties":false},"output_schema":{"type":"object","properties":{"data":{"type":"object","properties":{"total_value":{"type":"string","description":"Total portfolio value across all asset types. The default 'account value' to show the user."},"equity_value":{"type":"string","description":"Value of stock and ETF positions."},"options_value":{"type":"string","description":"Value of options positions."},"futures_value":{"type":"string","description":"Value of futures positions (includes RHD cost basis)."},"event_contracts_value":{"type":"string","description":"Value of event contract positions."},"crypto_value":{"type":"string","description":"Value of crypto holdings."},"cash":{"type":"string","description":"Available cash (includes early access from pending deposits)."},"pending_deposits":{"type":"string","description":"Deposits in transit, not yet settled."},"mutual_funds_value":{"type":"string","description":"Value of mutual fund positions."},"fixed_income_value":{"type":"string","description":"Value of fixed income instruments."},"currency":{"type":"string","description":"Currency all values are denominated in (e.g. USD)."},"buying_power":{"type":["null","object"],"properties":{"buying_power":{"type":"string","description":"Authoritative spendable figure used to gate order placement. For margin-enabled accounts it already includes available margin leverage; for cash and leverage-disabled accounts it equals the cash-only figure."},"unleveraged_buying_power":{"type":"string","description":"Buying power ignoring margin leverage. Typically <= buying_power. Negative when the account is in deficit — new positions cannot be opened until the deficit is cleared."},"intraday_buying_power":{"type":["null","string"],"description":"Buying power for intraday leverage, when applicable; null when the account does not have intraday margin enabled."},"off_intraday_buying_power":{"type":["null","string"],"description":"Buying power outside the intraday-leverage window; null when not applicable."},"display_currency":{"type":"string","description":"Currency of the figures, e.g. 'USD'."}},"description":"Real-time buying power from the broker.","required":["buying_power","unleveraged_buying_power","display_currency"],"additionalProperties":false},"crypto_buying_power":{"type":["null","object"],"properties":{"buying_power":{"type":"string","description":"Authoritative spendable figure for crypto buys (cash-only; excludes equity margin leverage)."}},"description":"Spendable buying power for crypto buys. Cash-only (crypto is not marginable), so it excludes the equity margin leverage that buying_power may include — quote this for 'how much can I spend on crypto'. Omitted when unavailable or when the caller is not in the crypto experiment.","required":["buying_power"],"additionalProperties":false}},"description":"Tool-specific result payload; see the inner properties for fields.","required":["total_value","equity_value","options_value","futures_value","event_contracts_value","crypto_value","cash","pending_deposits","mutual_funds_value","fixed_income_value","currency","buying_power"],"additionalProperties":false},"guide":{"type":"string","description":"Show total_value as "account value" or "portfolio value". The breakdown fields show how value is distributed across asset types. Zero-value fields mean the user has no holdings in that asset class — omit them from display unless the user explicitly asks. For "how much cash do I have?" use the cash field. buying_power is the real-time authoritative spendable figure from the broker; quote buying_power.buying_power as the primary affordability answer with buying_power.display_currency. For "how much can I spend on crypto?" quote crypto_buying_power.buying_power instead — crypto is cash-only (not marginable), so the top-level buying_power may overstate it; crypto_buying_power is omitted when unavailable. crypto_value reflects the user's crypto holdings value. On a cash account, recently sold proceeds that have not yet settled are not spendable and are not included in buying_power; that unsettled amount is reported as unsettled_funds by get_accounts (not here), so if you do not already have the account's unsettled_funds, call get_accounts to check it. Whenever you report buying power or account value for a type='cash' account whose unsettled_funds is greater than 0, inform the user those unsettled proceeds could be traded immediately with a limited-margin upgrade, and — if the get_limited_margin_upgrade_info tool is available — call it with the account_number and share the appropriate upgrade link. If that tool is not available, say nothing about limited margin (there is no fallback)."}},"required":["data","guide"],"additionalProperties":false},"annotations":{"readOnlyHint":true},"execution":null,"shape_hash":"sha256:b09a4452961a36843932fa7d738e99f32831a708092529f08e7dc8eb2c328847","contract_hash":"sha256:9063b03e5922ed0ad2d49831c0cc1c868c8397ea109b6e84b39aaa5ef617ba7c"},"category":"read.balances","arguments":{"account_number":"{account_id}"},"result":{"items":"data","account":"{account_id}","cash":"cash"},"reason":"This reads the cash balance for one specified brokerage account.","warnings":[],"original":{"name":"get_portfolio","category":"read.balances","arguments":{"account_number":"{account_id}"},"result":{"items":"data","account":"{account_id}","cash":"cash"},"reason":"This reads the cash balance for one specified brokerage account.","warnings":[]},"edits":[]},"get_realized_pnl":{"contract":{"name":"get_realized_pnl","title":null,"description":"Get a customer's realized profit & loss for an account over a time window — per-bucket realized gain ($ and %) and the number of closing trades, plus window totals. Read-only. Aggregate, bucketed numbers only (not individual trades). Use for post-trade analysis like "how did my last 90 days of trades do?".","input_schema":{"type":"object","properties":{"account_number":{"type":"string","description":"Brokerage account number (the rhs_account_number from get_accounts). Obtain it from get_accounts."},"span":{"type":"string","description":"Preset window: day, week, month, 3month, year, or all. Defaults to 3month ('last 90 days'). Mutually exclusive with start_date/end_date."},"start_date":{"type":"string","description":"Custom window start, YYYY-MM-DD, inclusive — interpreted at midnight in timezone (default US Eastern). Use with end_date instead of span; must be on or before end_date and not in the future."},"end_date":{"type":"string","description":"Custom window end, YYYY-MM-DD, inclusive — the entire end_date is covered (through 23:59:59 in timezone). Use with start_date instead of span; an end_date beyond today returns data through the present."},"asset_classes":{"type":["null","array"],"items":{"type":"string"},"description":"Filter to one or more of equity, option, crypto. Omit for all asset classes available on the account."},"display_currency":{"type":"string","description":"Currency for returned amounts. Currently USD only; defaults to USD."},"timezone":{"type":"string","description":"IANA timezone for bucket day-boundaries (e.g. America/New_York). Defaults to the account timezone (US Eastern)."}},"required":["account_number"],"additionalProperties":false},"output_schema":{"type":"object","properties":{"data":{"type":"object","properties":{"account_number":{"type":"string","description":"The account the realized profit and loss is for (echoed)."},"window":{"type":"string","description":"The window actually used — the span name, or 'start_date..end_date' for a custom range."},"display_currency":{"type":"string","description":"Currency the amounts are denominated in."},"data_points":{"type":["null","array"],"items":{"type":"object","properties":{"start_time":{"type":"string","description":"RFC3339 start of the bucket window (inclusive)."},"end_time":{"type":"string","description":"RFC3339 end of the bucket window."},"realized_gain":{"type":["null","string"],"description":"Realized profit/loss in the bucket, decimal string in display_currency. Null when the bucket's realized profit and loss is not meaningful (e.g. all lots are transfers with no cost basis) — present it as 'n/a', not 0."},"rate_of_realized_gain":{"type":["null","string"],"description":"Bucket realized return as a percentage, decimal string (e.g. '10' = 10%). Null for transfer-only buckets with no cost basis — the same condition that nulls realized_gain; present as 'n/a', not 0."},"number_of_trades":{"type":"integer","description":"Count of closing/realizing trades in the bucket.","minimum":-2147483648,"maximum":2147483647}},"required":["start_time","end_time","realized_gain","rate_of_realized_gain","number_of_trades"],"additionalProperties":false},"description":"Realized-profit-and-loss buckets in ascending time order. Empty when there were no closing trades in the window."},"total_returns":{"type":"string","description":"Total realized profit and loss across the window, decimal string in display_currency. '0' when the window had no closing trades."},"total_rate_of_return":{"type":"string","description":"Total realized return across the window as a percentage, decimal string."}},"description":"Tool-specific result payload; see the inner properties for fields.","required":["account_number","window","display_currency","data_points","total_returns","total_rate_of_return"],"additionalProperties":false},"guide":{"type":"string","description":"This is realized profit & loss only — gains/losses from positions closed within the window; it excludes unrealized profit and loss on open positions. data_points are buckets in ascending time order. A window with no closing trades returns empty data_points with zero totals — that is a valid result ("no realized trades in this window"), not an error. When a bucket's realized_gain and rate_of_realized_gain are null (a transfer-only bucket whose lots had no cost basis, e.g. transfers), present them as "n/a" — do not render them as $0 / 0%. These are aggregate numbers; for individual trade records use the separate realized profit and loss (trade history) tool. Treat figures as informational, not a tax document or tax/performance advice."}},"required":["data","guide"],"additionalProperties":false},"annotations":{"readOnlyHint":true},"execution":null,"shape_hash":"sha256:baedcd1b4c9fafcfc427cdb9d6ee0e8f71d555c470b9642ce2cc6da0f5650538","contract_hash":"sha256:64e3c98d4fe20fd2ccbb92411c8ad90b586275cad2af42ba1e7aff76c4febee5"},"category":null,"arguments":{},"result":{},"reason":"Realized profit and loss has no matching callable category in this profile.","warnings":[],"original":{"name":"get_realized_pnl","category":null,"arguments":{},"result":{},"reason":"Realized profit and loss has no matching callable category in this profile.","warnings":[]},"edits":[]},"get_scanner_filter_specs":{"contract":{"name":"get_scanner_filter_specs","title":null,"description":"List every valid scanner filter type and how to use it. Call this before constructing filters for create_scan or update_scan_filters — do not guess filter_type names.

This tool takes no parameters.","input_schema":{"type":"object","additionalProperties":false},"output_schema":{"type":"object","properties":{"data":{"type":"object","properties":{"filter_specs":{"type":["null","array"],"items":{"type":"object","properties":{"filter_type":{"type":"string","description":"Wire-format enum name, e.g. "FILTER_TYPE_RSI". Pass this in filter payloads."},"display_name":{"type":"string","description":"Human-readable name as shown in Legend, e.g. "RSI"."},"filter_group":{"type":"string","description":"Category bucket: POPULAR, TECHNICAL, FUNDAMENTAL, OPTION, or PRICE_VOLUME."},"value_type":{"type":"string","description":"Expected value format: DECIMAL, INTEGER, DATETIME, or STRING."},"unit_type":{"type":"string","description":"Value unit: DOLLAR, PERCENTAGE, or PLAIN. PERCENTAGE filters take DECIMAL values: 0.05 means 5%, so send 0.05 and never 5 (which reads as 500% and silently matches nothing). Same convention as the Legend UI, which converts percent input to decimals before sending."},"supported_predicates":{"type":["null","array"],"items":{"type":"string"},"description":"Symbolic predicates valid for this filter (e.g. ">", "<", "BETWEEN")."},"supported_lengths":{"type":["null","array"],"items":{"type":"integer","minimum":-2147483648,"maximum":2147483647},"description":"Lookback lengths the filter accepts (e.g. [9, 14, 21, 50] for RSI). Empty when the filter has no length input."},"supported_intervals":{"type":["null","array"],"items":{"type":"string"},"description":"Time granularities the filter accepts (e.g. ["1m", "5m", "1h", "1d"]). Empty when the filter has no interval input."},"supported_plots":{"type":["null","array"],"items":{"type":"string"},"description":"Plot / price-field values the filter accepts (e.g. ["open", "close"] for % Change). Empty when the filter has no plot input."},"options":{"type":["null","array"],"items":{"type":"string"},"description":"The complete set of values this filter accepts, for filters that take a value from a fixed vocabulary rather than a threshold (asset type, sector). Send one of these verbatim in the filter's values: they are case-sensitive, and a value outside the set is rejected. Empty for threshold filters, whose values are numbers."}},"required":["filter_type","display_name","filter_group","value_type","unit_type","supported_predicates"],"additionalProperties":false},"description":"Every valid scanner filter type: wire-format enum name, category, value format, supported predicates/intervals/lengths/plots, and the enumerated options a vocabulary filter accepts."}},"description":"Tool-specific result payload; see the inner properties for fields.","required":["filter_specs"],"additionalProperties":false},"guide":{"type":"string","description":"Match filter_type exactly, including suffixes (e.g. percent-change filters use FILTER_TYPE_PERCENT_CHANGE_FROM_CLOSE, not FILTER_TYPE_PERCENT_CHANGE). If a filter's supported_intervals is non-empty, pass an interval — omitting it is the leading cause of an otherwise-valid filter returning no results. Use supported_predicates symbols exactly (e.g. ">", "BETWEEN").

No enum filter scopes a scan to particular instruments: to restrict it to named tickers or to an index's members, use an expression filter on the symbol field (get_scanner_datapoints, descriptive category) rather than concluding it cannot be done.

If a filter has options, its values must come from that list verbatim — it is the filter's complete vocabulary, and anything else is rejected. Do not infer these values from scan results: the instrument_type field in results is Robinhood's classification, which is coarser than the asset-type filter's (its EQUITY spans both STOCK and ETF), so a value copied from there screens for nothing.

Filters with unit_type PERCENTAGE take DECIMAL values: 0.05 means 5%. A whole-percent number silently matches nothing — "implied volatility above 80" is values ["0.8"], because ["80"] reads as 8000% and returns zero rows with no error. This applies to every PERCENTAGE filter (implied and historical volatility, IV rank, the margins, return on assets/equity, % change, gap)."}},"required":["data","guide"],"additionalProperties":false},"annotations":{"readOnlyHint":true},"execution":null,"shape_hash":"sha256:d6cd8f59fb267fd53391cba8973568d15a284e1738b79c36c7af4c2d514adedd","contract_hash":"sha256:4d142bd653c83dd9abd8587f71fd2bb3f78dca5a5793224a965760af5a63ddd3"},"category":null,"arguments":{},"result":{},"reason":"Scans are outside this broker profile’s scope.","warnings":[],"original":{"name":"get_scanner_filter_specs","category":null,"arguments":{},"result":{},"reason":"Scans are outside this broker profile’s scope.","warnings":[]},"edits":[]},"get_scans":{"contract":{"name":"get_scans","title":null,"description":"List the authenticated user's saved scanners (also called screeners). A scan is a saved set of filters and columns that filters the market for instruments matching specific criteria (e.g. "RSI > 70 and Volume > 1M"). The user creates these in Legend or via the create_scan tool.

Returns one entry per scan with its id, title, active filters, configured columns, sort order, and a flag indicating whether the scan is managed by Cortex (Legend's AI agent). Cortex-managed scans are read-only via MCP — they can be run with run_scan but not modified with update_scan_filters or update_scan_config.

This tool takes no parameters.","input_schema":{"type":"object","additionalProperties":false},"output_schema":{"type":"object","properties":{"data":{"type":"object","properties":{"scans":{"type":["null","array"],"items":{"type":"object","properties":{"scan_id":{"type":"string","description":"Unique scan identifier. Pass this to run_scan, update_scan_filters, or update_scan_config."},"title":{"type":"string","description":"Human-readable name the user gave the scan."},"filter_summary":{"type":["null","array"],"items":{"type":"object","properties":{"filter_type":{"type":"string","description":"Display label of the column this filter screens on, as shown in Legend (e.g. "RSI", "Market cap"). This is a user-editable label, so it is for describing the filter to the user — do NOT send it back as filter_type when re-applying filters; use filter_type_enum for that."},"filter_type_enum":{"type":"string","description":"Wire-format enum name for this filter (e.g. "FILTER_TYPE_RSI") — the value to pass as a filter's filter_type when re-sending this filter to create_scan or update_scan_filters. FILTER_TYPE_CUSTOM is the exception: such a filter is defined by its expression, so re-create it by sending the expression field to create_scan and omitting filter_type. Never send FILTER_TYPE_CUSTOM as a filter_type — it would create an empty filter. Empty only when the filter has no recognized type."},"predicate":{"type":"string","description":"Comparison operator in symbolic form (e.g. ">", "<", "BETWEEN")."},"values":{"type":["null","array"],"items":{"type":"string"},"description":"Threshold values for the predicate. Single-element for >/</=, two-element for BETWEEN, multi-element for IN_LIST/ANY_OF."},"interval":{"type":"string","description":"Time granularity for time-series filters (e.g. "1d", "1h"). Empty for snapshot filters."},"length":{"type":"integer","description":"Lookback length for filters that need one (e.g. RSI period of 14). Zero/omitted for filters that don't take a length.","minimum":-2147483648,"maximum":2147483647},"plot":{"type":"string","description":"Plot / price-field input for filters that have one (e.g. % Change uses "open" or "close" to choose changeFromOpen vs changeFromClose). Empty for filters that don't take a plot."},"expression":{"type":"string","description":"Upstream market-data expression this filter screens on. Populated for every filter, standard or custom — an enum filter type is a preset that compiles to an expression upstream. Useful for explaining precisely what the filter measures (which interval, lookback and session it uses). When re-applying a standard filter, send filter_type_enum rather than this; for a FILTER_TYPE_CUSTOM filter this expression is exactly what to send, as the expression field of a create_scan filter."}},"required":["filter_type","predicate","values"],"additionalProperties":false},"description":"Active filters applied to this scan, one entry per filter. Empty when the scan uses only preset defaults."},"column_count":{"type":"integer","description":"Number of visible columns configured on this scan. Equals the number of columns entries with visible true."},"columns":{"type":["null","array"],"items":{"type":"object","properties":{"display_name":{"type":"string","description":"Column header as shown in Legend, e.g. "% Change". This is the value other scanner tools take when they reference a column."},"visible":{"type":"boolean","description":"False for a column configured on the scan but hidden from the results table. Hidden columns still appear here but their values are absent from scan results."},"order":{"type":"integer","description":"Zero-based position of this column in the results table.","minimum":-2147483648,"maximum":2147483647},"expression":{"type":"string","description":"Upstream market-data expression this column computes, e.g. dayVolume or fundamental.marketCap. Populated for every column, standard or custom — a named column is a preset that compiles to an expression upstream. Read-only explanatory detail: reference a column by display_name, never by this."}},"required":["display_name","visible","order"],"additionalProperties":false},"description":"Every column configured on this scan, visible or not, in configuration order. Use the display_name values here as the sorting_column argument to update_scan_config — that argument matches on display name and is case-sensitive."},"sorting":{"type":"string","description":"Current sort column + direction in human form (e.g. "Volume desc"). Empty when no sort is configured."},"cortex_managed":{"type":"boolean","description":"True when this scan was created or modified by Cortex (Legend's AI agent). Cortex-managed scans can be read but not modified via MCP tools."}},"required":["scan_id","title","filter_summary","column_count","columns","cortex_managed"],"additionalProperties":false},"description":"List of the user's saved scans, newest first. Empty when the user has no saved scans."}},"description":"Tool-specific result payload; see the inner properties for fields.","required":["scans"],"additionalProperties":false},"guide":{"type":"string","description":"How to interpret the response:
- scans is an array, newest first. Empty when the user has no saved scans — offer to create one with create_scan if they ask.
- filter_summary on each scan describes the active filters. Use filter_type (e.g. "RSI"), predicate, values and optional interval/length to tell the user what the scan does. To re-send a filter to update_scan_filters or create_scan, copy filter_type_enum — not filter_type, which is a user-editable column label and will be rejected.
- A filter whose filter_type_enum is FILTER_TYPE_CUSTOM is defined by its expression. update_scan_filters cannot carry it over; to change a scan that has one, use create_scan with that scan's scan_id and the full intended filter set, passing the filter's expression in the expression field (the scan gets a new configuration version; earlier versions are preserved).
- cortex_managed: true means the scan was created or modified by Cortex inside Legend. Tell the user it's read-only via MCP if they ask to modify it. Suggest creating a fresh scan via create_scan as the alternative.
- columns lists every configured column, hidden ones included; column_count counts only the visible ones. When the user asks to re-sort a scan, take update_scan_config's sorting_column verbatim from a columns[].display_name — never guess it.
- Columns are writable: to add, remove or reorder a scan's extra columns (the ones beyond its filters' own and the standard defaults), call update_scan_config with the complete intended columns list — it keeps the scan's filters, expression filters included, without re-sending them. Each entry here carries the display_name and expression to copy from.
- sorting describes the scan's current sort (e.g. "Volume desc"). Mention it when summarizing how results would be ordered.
- Use scan_id (not title) when calling run_scan, update_scan_filters, or update_scan_config.

When presenting scans to the user:
- Render as a numbered list with the title prominent and a short summary of filters.
- Mark Cortex-managed scans clearly so the user knows they're read-only here.
- If the user wants to see results, ask which scan and call run_scan with that scan_id."}},"required":["data","guide"],"additionalProperties":false},"annotations":{"readOnlyHint":true},"execution":null,"shape_hash":"sha256:7d5ef7bbe165dee5b70a179843817b5f5e3b776b9c88e228ad3fa66243245b5f","contract_hash":"sha256:49da6dc587247550d32e497edc3188c53b2ec5cd8feaf8cb7b01afa600c6811b"},"category":null,"arguments":{},"result":{},"reason":"Scans are outside this broker profile’s scope.","warnings":[],"original":{"name":"get_scans","category":null,"arguments":{},"result":{},"reason":"Scans are outside this broker profile’s scope.","warnings":[]},"edits":[]},"get_sec_filing":{"contract":{"name":"get_sec_filing","title":null,"description":"Read an SEC filing's table of contents or a specific section's text. Use get_sec_filing_index to find a filing_id first.","input_schema":{"type":"object","properties":{"filing_id":{"type":"string","description":"Filing identifier returned by get_sec_filing_index."},"section":{"type":"string","description":"Section identifier from the table of contents (the id field). Omit to get the full table of contents; provide to get a specific section's text."}},"required":["filing_id"],"additionalProperties":false},"output_schema":{"type":"object","properties":{"data":{"type":"object","properties":{"table_of_contents":{"type":["null","object"],"properties":{"filing_id":{"type":"string","description":"Filing identifier, echoed from the request."},"form_type":{"type":"string","description":"SEC form type of this filing, e.g. '10-K'."},"sections":{"type":["null","array"],"items":{"type":["null","object"],"properties":{"id":{"type":"string","description":"Slugified section identifier. Pass as the section param to get_sec_filing to retrieve this section's text."},"title":{"type":"string","description":"Section heading text as it appears in the filing."},"level":{"type":"integer","description":"Heading depth: 1 = top-level part, 2 = item, 3 = sub-item."}},"required":["id","title","level"],"additionalProperties":false},"description":"All sections in the filing, in document order. Pick a section id and call get_sec_filing again with that id to read the text."}},"description":"Table of contents for the filing. Populated when no section is requested. Pick a section id from sections and call get_sec_filing with it to read the text.","required":["filing_id","form_type","sections"],"additionalProperties":false},"section":{"type":["null","object"],"properties":{"filing_id":{"type":"string","description":"Filing identifier, echoed from the request."},"form_type":{"type":"string","description":"SEC form type of this filing, e.g. '10-K'."},"section_id":{"type":"string","description":"Section identifier, echoed from the request."},"section_title":{"type":"string","description":"Section heading text."},"content":{"type":"string","description":"Full markdown text of the section. May be several thousand tokens for narrative sections like MD&A."}},"description":"The requested section's text and metadata. Populated only when a section id was provided.","required":["filing_id","form_type","section_id","section_title","content"],"additionalProperties":false}},"description":"Tool-specific result payload; see the inner properties for fields.","additionalProperties":false},"guide":{"type":"string","description":"When section is omitted, table_of_contents is populated and section is absent — pick a section id and call get_sec_filing again with that id. When section is provided, section is populated and table_of_contents is absent. Section content can be several thousand tokens for narrative sections (e.g. MD&A); prefer fetching one section at a time. If the filing has not yet been processed or the section id did not match, an error will be returned."}},"required":["data","guide"],"additionalProperties":false},"annotations":{"readOnlyHint":true},"execution":null,"shape_hash":"sha256:c2ff88428e0a9dba983af18d9f9c1f8f3e193f7e2cb15ef6697e0e49805b46ea","contract_hash":"sha256:b7233e659f3192b41bfd360e3120c2909e296b965a668dbcbcf137e386242891"},"category":null,"arguments":{},"result":{},"reason":"SEC filings are outside this broker profile’s scope.","warnings":[],"original":{"name":"get_sec_filing","category":null,"arguments":{},"result":{},"reason":"SEC filings are outside this broker profile’s scope.","warnings":[]},"edits":[]},"get_sec_filing_facts":{"contract":{"name":"get_sec_filing_facts","title":null,"description":"Get reported facts tagged under specific GAAP concept names in one or more SEC filings — financial figures (revenue, net income, assets, debt) and disclosures (e.g. debt schedules, related-party transactions, subsequent events) alike. Use get_sec_filing_index to find filing_ids first.","input_schema":{"type":"object","properties":{"filing_ids":{"type":["null","array"],"items":{"type":"string"},"description":"Filing identifiers to fetch facts for (1-3), from get_sec_filing_index. Default to a single filing_id — most questions are answered by periods already embedded in one filing (10-Ks carry ~3 fiscal years, 10-Qs carry current + prior-year). Pass more than one only when the question needs data a single filing structurally can't have, e.g. a trend longer than 3 years, or confirming a disclosed subsequent event landed in the next filing."},"concepts":{"type":["null","array"],"items":{"type":"string"},"description":"GAAP concept names to fetch (1-10) — covers numeric line items (e.g. NetIncomeLoss, Assets, Revenues) and disclosure text blocks (e.g. ScheduleOfDebtTableTextBlock) alike. Guess common names directly; only call get_sec_filing_facts_catalog first if a guess comes back with no matching facts."}},"required":["filing_ids","concepts"],"additionalProperties":false},"output_schema":{"type":"object","properties":{"data":{"type":"object","properties":{"facts":{"type":["null","array"],"items":{"type":["null","object"],"properties":{"filing_id":{"type":"string","description":"Filing identifier this fact was reported in, from get_sec_filing_index."},"concept":{"type":"string","description":"GAAP taxonomy concept name, e.g. NetIncomeLoss, Assets. Echoed from the request."},"entity":{"type":"string","description":"Filer identifier (CIK) this fact was reported under."},"period":{"type":"string","description":"Reporting period as reported: either a single date (instant, e.g. balance-sheet items) or a start/end date range (duration, e.g. income-statement items)."},"axises":{"type":["null","array"],"items":{"type":"string"},"description":"Dimension breakdown for this fact, e.g. ['ProductOrServiceAxis: HardwareMember']. Empty means this is the undifferentiated total for the concept and period — prefer it as 'the total' when both a totals row and axis-sliced rows exist."},"decimals":{"type":["null","integer"],"description":"Reported precision as a power of 10, e.g. -6 means rounded to the nearest million. Absent for text-valued facts. The same concept can appear at different precisions across facts in one filing (e.g. -6 vs -7) — don't assume uniform precision when doing raw arithmetic across multiple rows."},"value":{"type":["null","string"],"description":"Numeric value as reported, a decimal string. Absent when this fact is text-valued — see char_value instead."},"char_value":{"type":"string","description":"Text value as reported (e.g. footnote/disclosure text-block content). Empty when this fact is numeric-valued — see value instead. A populated value can still be just a section heading rather than a narrative; don't assume any non-empty text is informative. Substantial disclosures (e.g. debt schedules) can run to several thousand tokens — fetch text-block concepts deliberately, not as part of a broad speculative batch."},"unit":{"type":["null","string"],"description":"Unit of the numeric value, e.g. USD, shares. Absent for text-valued facts."},"start_date":{"type":["null","string"],"description":"Start of the reporting period. Absent for instant (point-in-time) facts, e.g. balance-sheet items."},"end_date":{"type":"string","description":"End of the reporting period, or the instant date for point-in-time facts."}},"required":["filing_id","concept","entity","period","axises","char_value","end_date"],"additionalProperties":false},"description":"Matching fact rows, one per filing/concept/period/axis combination found. Empty when none of the requested concepts exist for the requested filings."}},"description":"Tool-specific result payload; see the inner properties for fields.","required":["facts"],"additionalProperties":false},"guide":{"type":"string","description":"Fetch known synonym/near-duplicate concept pairs together and cross-check for divergence — they can legitimately disagree (e.g. NetIncomeLoss with ProfitLoss, Revenues with RevenueFromContractWithCustomerExcludingAssessedTax). Not every similarly-named pair is the same failure mode: some are inconsistent tagging of the same thing (reconcile to one number, or flag the divergence if it's large); others are deliberately different scopes (e.g. DebtCurrent/LongTermDebt exclude finance leases, while LongTermDebtAndFinanceLeasesCurrent/LongTermDebtAndFinanceLeasesNoncurrent include them and will consistently run a few percent higher) — present those separately with what each includes rather than collapsing them into one number. A requested concept with no matching rows in the response simply does not exist for that filing — diff the concepts you requested against the concepts actually present before answering, and call get_sec_filing_facts_catalog if a load-bearing concept came back missing rather than answering off a partial set. Report a concept as not available rather than force-fitting a value that doesn't semantically match the question."}},"required":["data","guide"],"additionalProperties":false},"annotations":{"readOnlyHint":true},"execution":null,"shape_hash":"sha256:25dec5dc57bb0c70f3575d84dfe8e486eb7c7e4f0801e896c3befb00614415a0","contract_hash":"sha256:c630d80def4e1634c62cd2939ead7a55e107547a9e2764b6ca5a99a1fba9b816"},"category":null,"arguments":{},"result":{},"reason":"SEC filings and fundamentals are outside this broker profile’s scope.","warnings":[],"original":{"name":"get_sec_filing_facts","category":null,"arguments":{},"result":{},"reason":"SEC filings and fundamentals are outside this broker profile’s scope.","warnings":[]},"edits":[]},"get_sec_filing_facts_catalog":{"contract":{"name":"get_sec_filing_facts_catalog","title":null,"description":"List the distinct GAAP concept names tagged in an SEC filing, with their reporting periods and dimension breakdowns. Use this only after a direct get_sec_filing_facts guess comes back empty, or for open-ended "what's unusual/notable" questions — most common financial questions should guess concept names directly rather than calling this first.","input_schema":{"type":"object","properties":{"filing_id":{"type":"string","description":"Filing identifier to catalog, from get_sec_filing_index."},"concept_contains":{"type":"string","description":"Case-insensitive substring filter on concept name, e.g. 'Debt'. Omit to return all concepts."},"axis_name_in":{"type":["null","array"],"items":{"type":"string"},"description":"Only return concepts broken down by at least one of these dimension names. For 'what's unusual/notable in this filing' questions, try named-entity axes like SubsequentEventTypeAxis, BusinessAcquisitionAxis, RelatedPartyTransactionsByRelatedPartyAxis, LegalEntityAxis, or MajorCustomersAxis before falling back to an unfiltered call. Omit to skip this filter."},"offset":{"type":"integer","description":"Pagination offset. Omit for the first page; to fetch the next page, pass the value from the prior response's next_offset field."}},"required":["filing_id"],"additionalProperties":false},"output_schema":{"type":"object","properties":{"data":{"type":"object","properties":{"concepts":{"type":["null","array"],"items":{"type":["null","object"],"properties":{"concept":{"type":"string","description":"GAAP taxonomy concept name available for this filing. Pass to get_sec_filing_facts's concepts param to fetch its values."},"is_text_block":{"type":"boolean","description":"True when this concept holds narrative/disclosure text rather than a number — expect char_value, not value, on the fetched fact."},"periods":{"type":["null","array"],"items":{"type":["null","object"],"properties":{"period":{"type":"string","description":"Reporting period as reported: either a single date (instant) or a start/end date range (duration), matching the period field on get_sec_filing_facts rows."},"start_date":{"type":["null","string"],"description":"Start of the period. Absent for instant (point-in-time) periods."},"end_date":{"type":"string","description":"End of the period, or the instant date for point-in-time periods."}},"required":["period","end_date"],"additionalProperties":false},"description":"Distinct reporting periods this concept was tagged for in this filing."},"axis_names":{"type":["null","array"],"items":{"type":"string"},"description":"Dimension names this concept is broken down by in this filing, e.g. ['ProductOrServiceAxis']. Empty means only an undifferentiated total exists for this concept."}},"required":["concept","is_text_block","periods","axis_names"],"additionalProperties":false},"description":"Distinct concepts tagged in this filing, matching any filters applied."},"count":{"type":"integer","description":"Total number of concepts matching the request, across all pages."},"next_offset":{"type":["null","integer"],"description":"Present only when more concepts remain. Pass as the offset param on the next call to page through the rest."}},"description":"Tool-specific result payload; see the inner properties for fields.","required":["concepts","count"],"additionalProperties":false},"guide":{"type":"string","description":"If a filtered call (concept_contains or axis_name_in) returns nothing relevant, retry once without filters before giving up. If the unfiltered catalog still has nothing relevant, say clearly that it isn't available in this filing rather than guessing further. When a question spans multiple filings, call this tool once per filing_id — GAAP tagging can differ year to year, so one filing's catalog shouldn't be assumed to apply to another. Page size is set upstream and not fixed — always pass next_offset back exactly as returned rather than guessing an increment, and stop once a response has no next_offset."}},"required":["data","guide"],"additionalProperties":false},"annotations":{"readOnlyHint":true},"execution":null,"shape_hash":"sha256:395ab527cd0a05414a7098c5ffa6153c5c824bd655441c8d0b971d1e8c21a9c3","contract_hash":"sha256:d89f733fd03e09d710950b419e5be21d658a094b15a09e5ef8286ac14ffa2039"},"category":null,"arguments":{},"result":{},"reason":"SEC filings and fundamentals are outside this broker profile’s scope.","warnings":[],"original":{"name":"get_sec_filing_facts_catalog","category":null,"arguments":{},"result":{},"reason":"SEC filings and fundamentals are outside this broker profile’s scope.","warnings":[]},"edits":[]},"get_sec_filing_index":{"contract":{"name":"get_sec_filing_index","title":null,"description":"List a company's SEC filings, optionally filtered by form type and date. Use this to find a specific annual report (10-K), quarterly report (10-Q), or material event disclosure (8-K).","input_schema":{"type":"object","properties":{"symbol":{"type":"string","description":"Stock ticker symbol, e.g. AAPL. Exact match — no partial or name-based lookup. Lowercase input is normalized to uppercase."},"form_type":{"type":["null","array"],"items":{"type":"string"},"description":"One or more SEC form types to filter by, e.g. ['10-K'] or ['10-K','10-Q']. Omit to return all form types."},"since":{"type":"string","description":"Earliest filing date to include, ISO format YYYY-MM-DD. Omit to return filings from all dates."},"until":{"type":"string","description":"Latest filing date to include, ISO format YYYY-MM-DD. Omit to return filings up to the most recent."},"cursor":{"type":"string","description":"Pagination cursor. Omit for the first page; to fetch the next page, pass the value from the prior response's next field."}},"required":["symbol"],"additionalProperties":false},"output_schema":{"type":"object","properties":{"data":{"type":"object","properties":{"symbol":{"type":"string","description":"The requested ticker, in canonical uppercase form."},"filings":{"type":["null","array"],"items":{"type":["null","object"],"properties":{"filing_id":{"type":"string","description":"Unique identifier for this filing. Pass to get_sec_filing to read its content."},"form_type":{"type":"string","description":"SEC form type, e.g. '10-K' (annual report), '10-Q' (quarterly report), '8-K' (current report / material event)."},"description":{"type":"string","description":"Human-readable label for the form type, e.g. 'Annual Report'."},"date_filed":{"type":"string","description":"Date the filing was submitted to the SEC, YYYY-MM-DD."}},"required":["filing_id","form_type","description","date_filed"],"additionalProperties":false},"description":"Filings matching the request, most-recent-first. Empty when no filings match the filters."},"next":{"type":"string","description":"Pagination cursor for the next page. Empty when there are no more results."}},"description":"Tool-specific result payload; see the inner properties for fields.","required":["symbol","filings"],"additionalProperties":false},"guide":{"type":"string","description":"If next is non-empty, more filings are available — call this tool again with the cursor value from next to fetch the next page. Results are most-recent-first. When the question doesn't need more than the most recent filing's own embedded history (most questions), use the first result rather than filtering further. When the question needs data spanning further back than one filing embeds — a multi-year trend beyond ~3 years, a specific past quarter, confirming a disclosed subsequent event's follow-through in the next filing — widen since/until and select up to 3 of the returned filings covering the needed span, then pass all of their filing_ids to get_sec_filing_facts. If a query with specific filters (form_type, since/until) returns no filings, retry once with the filters loosened (drop form_type, or widen/drop the date range) before giving up; if it's still empty, say clearly that no matching filing was found rather than guessing from an unrelated one."}},"required":["data","guide"],"additionalProperties":false},"annotations":{"readOnlyHint":true},"execution":null,"shape_hash":"sha256:651bad2769173e8bfe1b81d6c2fa95de678a736554c0899db3a15bd0618d4787","contract_hash":"sha256:1baa9ad67e7dcf751037dd2f572f83ca9826d73a70918225e3d58743ed779376"},"category":null,"arguments":{},"result":{},"reason":"SEC filings are outside this broker profile’s scope.","warnings":[],"original":{"name":"get_sec_filing_index","category":null,"arguments":{},"result":{},"reason":"SEC filings are outside this broker profile’s scope.","warnings":[]},"edits":[]},"get_watchlist_items":{"contract":{"name":"get_watchlist_items","title":null,"description":"List the items in a watchlist. Items may be stocks/ETFs, crypto pairs, futures, indexes — distinguished by object_type. For the options watchlist, use get_option_watchlist instead — this tool returns a generic shape that drops the strategy-specific fields and the upstream rejects it with 400 anyway. Does not return live prices; call get_quotes with the symbol(s) for that.","input_schema":{"type":"object","properties":{"list_id":{"type":"string","description":"UUID of the watchlist whose items to fetch. Obtain from get_watchlists or get_popular_watchlists."}},"required":["list_id"],"additionalProperties":false},"output_schema":{"type":"object","properties":{"data":{"type":"object","properties":{"items":{"type":["null","array"],"items":{"type":["null","object"],"properties":{"object_id":{"type":"string","description":"UUID of the underlying instrument / currency pair / futures contract / index. Pass to remove_from_watchlist (via symbol — the tool resolves it back to this id internally) to remove this item."},"object_type":{"type":"string","description":"What kind of asset this item references: 'instrument' (US stock/ETF), 'currency_pair' (crypto), 'futures' (futures contract), 'index' (market index), 'option_strategy' (options watchlist only), 'tokenized_stock'. Different object types are surfaced differently in the app."},"symbol":{"type":"string","description":"Human-readable ticker (e.g. 'AAPL' for instrument, 'BTC-USD' for currency_pair). May be empty for futures items if the upstream lookup failed."}},"required":["object_id","object_type"],"additionalProperties":false},"description":"Items in the watchlist."},"has_futures_contracts":{"type":"boolean","description":"True when at least one item is a futures contract. Mention to the user when surfacing items so they know which rows are futures."}},"description":"Tool-specific result payload; see the inner properties for fields.","required":["items","has_futures_contracts"],"additionalProperties":false},"guide":{"type":"string","description":"For instruments (object_type=instrument) the symbol is the ticker — pass to get_quotes for prices. For crypto (currency_pair), symbol is the pair (BTC-USD). The has_futures_contracts flag at the top tells you whether any futures items are present — futures behavior is different (the object_id is the active contract, not the product). When presenting to the user, lead with symbol + object_type; omit object_id unless asked."}},"required":["data","guide"],"additionalProperties":false},"annotations":{"readOnlyHint":true},"execution":null,"shape_hash":"sha256:6596b2611f8bb311f7aed0a983a058d622957a05d2f5db18a25eb6b7c0f966d3","contract_hash":"sha256:b2aa4bde589948e3bda4f4ddd32a3106c8e219b859cde50a8186f739cfbca70f"},"category":null,"arguments":{},"result":{},"reason":"Watchlists are outside this broker profile’s scope.","warnings":[],"original":{"name":"get_watchlist_items","category":null,"arguments":{},"result":{},"reason":"Watchlists are outside this broker profile’s scope.","warnings":[]},"edits":[]},"get_watchlists":{"contract":{"name":"get_watchlists","title":null,"description":"List the user's watchlists, including both user-created custom lists and Robinhood-curated lists the user follows. Use to look up list_id values for other watchlist tools.","input_schema":{"type":"object","additionalProperties":false},"output_schema":{"type":"object","properties":{"data":{"type":"object","properties":{"watchlists":{"type":["null","array"],"items":{"type":["null","object"],"properties":{"id":{"type":"string","description":"List UUID. Pass to other watchlist tools (get_watchlist_items, add/remove_from_watchlist, update_watchlist) as list_id."},"display_name":{"type":"string","description":"Human-readable list name."},"display_description":{"type":"string","description":"Optional short description shown under the name."},"icon_emoji":{"type":"string","description":"Emoji shown alongside the name. Present on custom lists; absent on Robinhood-curated lists."},"owner_type":{"type":"string","description":"'custom' means a user-created list. 'robinhood' means a curated list the user is following. Use this to distinguish user-owned lists (writable: rename, delete items, add items) from curated lists (read + follow/unfollow only)."},"item_count":{"type":"integer","description":"Number of items in the list."},"allowed_object_types":{"type":["null","array"],"items":{"type":"string"},"description":"Which kinds of objects can be added to this list. Common values: instrument (US stock/ETF), currency_pair (crypto), index (market index), option_strategy (options watchlist — see add_option_to_watchlist), futures. add_to_watchlist supports instrument, currency_pair, and index; options use the dedicated add_option_to_watchlist tool; futures still require the Robinhood app."}},"required":["id","display_name","owner_type","item_count"],"additionalProperties":false},"description":"One entry per watchlist the user has created or follows."}},"description":"Tool-specific result payload; see the inner properties for fields.","required":["watchlists"],"additionalProperties":false},"guide":{"type":"string","description":"Distinguish lists by owner_type: 'custom' lists are writable (add_to_watchlist, remove_from_watchlist, update_watchlist); 'robinhood' lists are read-only and managed via follow_watchlist / unfollow_watchlist. When the user picks a list to act on, prefer matching by display_name and confirm before destructive actions."}},"required":["data","guide"],"additionalProperties":false},"annotations":{"readOnlyHint":true},"execution":null,"shape_hash":"sha256:d03582a04567904aada8f7d63790fcfb6a324736875d50deecdf5235f264b6c1","contract_hash":"sha256:338d47270056072edc02b0ba99c47fe7f8fa94e6efaeae8453d67bba281ed974"},"category":null,"arguments":{},"result":{},"reason":"Watchlists are outside this broker profile’s scope.","warnings":[],"original":{"name":"get_watchlists","category":null,"arguments":{},"result":{},"reason":"Watchlists are outside this broker profile’s scope.","warnings":[]},"edits":[]},"place_crypto_order":{"contract":{"name":"place_crypto_order","title":null,"description":"Place a real crypto order with real money. Parameters mirror preview_crypto_order plus the optional ref_id. Requires an agentic-enabled crypto account.

Workflow: by default call preview_crypto_order first, present the estimated cost/credit and any validation errors, and get explicit user confirmation before calling this tool. Skip the preview only when the user has very explicitly asked to bypass it — a generic "place this order" is NOT a bypass.

Idempotency: pass a fresh UUID as ref_id on the first call for each logical order, and re-send the SAME ref_id on retries of transient failures. Use a new ref_id only when the user wants a new order.

Parameter rules:
- Provide exactly one of quantity or dollar_amount; dollar_amount works with every type.
- limit_price is required for limit and stop_limit; stop_price is required for stop_loss and stop_limit.
- symbol is resolved to a currency pair before placement; pass a bare asset symbol (e.g. 'BTC') or a pair ('BTC-USD').","input_schema":{"type":"object","properties":{"rhs_account_number":{"type":"string","description":"Numeric brokerage account number (the 'rhs_account_number' field on get_accounts entries — distinct from the alphanumeric 'account_number'). Must be an agentic-enabled crypto account. Required."},"symbol":{"type":"string","description":"Crypto symbol (e.g. 'BTC', 'ETH', or 'BTC-USD'). Resolved to a currency pair before the order is placed. Required."},"side":{"type":"string","description":"'buy' or 'sell'. Required."},"type":{"type":"string","description":"'market', 'limit', 'stop_loss', or 'stop_limit'. Required. 'stop_loss' is a stop-triggered market order — despite the name it applies to buy stops too; the equity/option tools call the same concept 'stop_market'. ALWAYS call these by their app names when speaking to the user, including when listing what types are supported: 'stop_loss' is a 'stop order' and 'stop_limit' a 'stop limit order'; the raw values are tool inputs only. A user asking for a 'stop loss', 'stop order', or 'stop market' order means this stop_loss type — do not ask which stop type (but a limit price given alongside the trigger makes it stop_limit); ask only when the phrasing names no type, e.g. a bare 'stop' or 'protect my position'."},"quantity":{"type":"string","description":"Asset quantity to trade (e.g. amount of BTC). Provide exactly one of quantity or dollar_amount. Crypto is measured in coins/units, not shares — when speaking to the user, including order confirmations, NEVER call a crypto quantity 'shares' ('shares' is equity terminology); state the amount of the asset, e.g. '0.001542 ETH'."},"dollar_amount":{"type":"string","description":"USD notional (e.g. '100.00'). Valid with every order type. Provide exactly one of quantity or dollar_amount. For market, quantity is derived server-side: a buy is sized at the current market price — the same sizing as the app — so the typical debit is ~dollar_amount, with a worst case up to ~1% more if the price moves before execution (the buy collar); a sell is likewise sized at the current market price, so the typical credit is ~dollar_amount, with a worst case up to ~5% less if the price moves before execution (the sell collar). For stop_loss, quantity is derived from dollar_amount at stop_price (the trigger price) when the order is placed, not the live quote — the triggered market order executes near the trigger, so the typical fill notional is ~dollar_amount, with a worst case up to the collar worse (a higher debit for buy stops, a lower credit for sell stops). For limit and stop_limit, quantity is derived from dollar_amount at limit_price when the order is placed — fills execute at the limit price or better, so a buy's debit is capped at dollar_amount (no collar buffer; on fee-priced accounts fee rounding can add at most one cent) and a sell's credit is at least the derived quantity's worth at the limit, minus any fee. On fee-priced accounts a buy's quantity is sized from the fee-netted amount so the total debit targets dollar_amount, and a sell's fee is deducted from the credit."},"limit_price":{"type":"string","description":"Limit price; required for limit and stop_limit."},"stop_price":{"type":"string","description":"Stop trigger price; required for stop_loss and stop_limit."},"time_in_force":{"type":"string","description":"Allowed values depend on type. market and limit: 'gtc' (good till canceled) only — market orders execute immediately so a bounded duration does not apply, and limit orders are always for 90 days; omit this field or pass 'gtc' for both. stop_loss and stop_limit: 'gtc' (good for 90 days), 'gfd' (good for day), 'gfw' (good for 7 days), or 'gfm' (good for 30 days). If omitted, defaults to gtc for market and limit, and gfd for stop_loss and stop_limit. 'ioc' is NEVER supported for crypto orders."},"ref_id":{"type":"string","description":"Idempotency key (UUID). Generate once per logical order and re-send the SAME value on retries of transient failures — the upstream deduplicates by ref_id. Omitting falls back to a server-generated key (loses client↔gateway idempotency). Use a new value only when the user wants a new order."}},"required":["rhs_account_number","symbol","side","type"],"additionalProperties":false},"output_schema":{"type":"object","properties":{"data":{"type":"object","properties":{"order":{"type":["null","object"],"properties":{"id":{"type":"string","description":"Order UUID. Needed by cancel_crypto_order (M2.2)."},"ref_id":{"type":"string","description":"Client-supplied idempotency key from order placement. Useful for reconciling agent-placed orders against records the agent kept."},"account_id":{"type":"string","description":"Crypto account UUID this order belongs to. Matches the account_id on get_crypto_positions rows."},"currency_pair_id":{"type":"string","description":"Pair UUID (e.g. BTC-USD). Pass to get_crypto_quotes for current price, or match against get_currency_pairs.id."},"currency_code":{"type":"string","description":"Asset currency code (e.g. 'BTC', 'ETH'). Useful for grouping orders by coin without joining against get_currency_pairs."},"side":{"type":"string","description":"'buy' or 'sell'."},"type":{"type":"string","description":"'market', 'limit', 'stop_loss', or 'stop_limit'. 'stop_loss' is a stop-triggered market order — despite the name it applies to buy stops too; the equity/option tools call the same concept 'stop_market'. ALWAYS call these by their app names when speaking to the user, including when listing what types are supported: 'stop_loss' is a 'stop order' and 'stop_limit' a 'stop limit order'; the raw values are tool inputs only."},"state":{"type":"string","description":"Raw lifecycle state: new, queued, unconfirmed, confirmed, partially_filled, filled, canceled, rejected, failed, voided. Combine with derived_state for clearer end-state classification."},"derived_state":{"type":"string","description":"Normalized lifecycle classification, e.g. 'open' / 'closed' / similar shorthand the upstream computes from raw state + fills. Prefer over state for user-facing summaries."},"state_group":{"type":"string","description":"'open' or 'closed' — the headline answer to 'is this order still working?'."},"time_in_force":{"type":"string","description":"'gtc' (good till canceled), 'gfd' (good for day), 'ioc' (immediate or cancel), 'gfw' (good for week), 'gfm' (good for month)."},"quantity":{"type":["null","string"],"description":"Originally-requested asset quantity. On dollar-based orders the server derives it at placement: from the quote for market and from the stop price for stop_loss (treat those as estimated until fills confirm them), and from the limit price for limit/stop_limit (exact at placement)."},"cumulative_quantity":{"type":"string","description":"Total asset quantity filled so far. Less than quantity while partially filled; equal once filled."},"canceled_quantity":{"type":["null","string"],"description":"Quantity that was canceled before fill (only populated on partial-fill-then-cancel paths)."},"price":{"type":["null","string"],"description":"Order price (interpretation depends on type — limit price for limit; for stop_loss it is the collared worst-case execution bound, NOT the trigger, which lives in stop_price; for market it is the raw quote side-price on a preview_crypto_order response — the same price the app displays, NOT collared — but the collared worst-case execution bound on placed orders; stablecoin pairs are never collared, so their preview and placed prices both carry the raw quote). Use limit_price / stop_price for the unambiguous fields."},"limit_price":{"type":["null","string"],"description":"Limit price for limit / stop_limit orders. Null for market / stop_loss."},"stop_price":{"type":["null","string"],"description":"Stop trigger price for stop_loss / stop_limit orders. Null for market / limit."},"average_price":{"type":["null","string"],"description":"Volume-weighted average fill price across executions. Null until the first fill."},"entered_price":{"type":["null","string"],"description":"Price the user originally entered (pre-collaring). Different from limit_price after server-side collaring adjusts the order."},"rounded_executed_notional":{"type":["null","string"],"description":"Total notional filled so far in the quote currency, rounded to 2 decimals."},"executions":{"type":["null","array"],"items":{"type":["null","object"],"properties":{"id":{"type":"string","description":"Execution UUID."},"price":{"type":"string","description":"Reported fill price per unit asset (e.g. USD per BTC). For the price the user actually paid after venue adjustments, use effective_price."},"effective_price":{"type":"string","description":"Per-unit price after venue fees or price adjustments are applied — closer to the user's realized fill economics than price."},"quantity":{"type":"string","description":"Asset quantity filled in this execution."},"notional":{"type":"string","description":"effective_price * quantity, rounded to 2 decimals where applicable."},"exchange_name":{"type":"string","description":"Routing venue name. Treat as informational; do not surface unless the user asks about routing."},"timestamp":{"type":"string","description":"When the fill occurred (UTC)."}},"required":["id","price","effective_price","quantity","notional","timestamp"],"additionalProperties":false},"description":"Per-fill detail. Reference for per-execution timing or price questions; for headline 'what did this fill at?' use average_price."},"initiator_type":{"type":"string","description":"Source that placed the order: 'api_trading', 'trading_view', 'recurring', 'paycheck', 'rh_assistant', 'agentic_trading' (when nummus adds that enum value), or one of the internal crypto-specific values. Tells the user whether they placed this order via app, API, recurring buy, or an agent."},"speculative":{"type":"boolean","description":"True when the order was created as a speculative pre-trade check (no upstream side effect). Should always be false on real placed orders; populated read-only by upstream."},"created_at":{"type":"string","description":"When the order was created (UTC)."},"updated_at":{"type":"string","description":"Last server-side state update (UTC) — fill, cancel, reject, etc."},"canceled_at":{"type":["null","string"],"description":"When the cancel was acknowledged. Null when the order has not been canceled."},"routing":{"type":"string","description":"How the order is routed for execution. Present verbatim as the routing line item; absent when routing information is unavailable."},"rounded_estimated_notional_with_estimated_fee":{"type":["null","string"],"description":"Estimated total cost (buy) or net proceeds (sell) in the quote currency, with ONLY the estimated fee already included. It does NOT include any additional taxes or deductions."},"rounded_uncollared_estimated_notional_with_estimated_fee":{"type":["null","string"],"description":"Same as rounded_estimated_notional_with_estimated_fee but before price collaring. Null when collaring does not apply."},"rounded_executed_notional_with_fee":{"type":["null","string"],"description":"Notional actually executed so far only including fees without netting additional taxes, in the quote currency. Grows as fills come in; 0 before the first fill. For the executed figure net of all taxes and fees use net_rounded_executed_notional."},"total_executed_notional":{"type":["null","string"],"description":"Total executed notional so far only including fees without netting additional taxes. Null until there are fills."},"net_rounded_estimated_notional":{"type":["null","string"],"description":"Estimated total cost (buy) or credit (sell) net of ALL taxes and fees. On a preview, present this as the estimated total cost or credit line item alongside the separate estimated_fee value. Never subtract the fee or taxes from it again. Null when an order has fills."},"net_rounded_executed_notional":{"type":["null","string"],"description":"Executed total cost (buy) or credit (sell) net of ALL taxes and fees — the definitive amount actually debited or credited. Null before the first fill. Grows as fills come in. Never subtract the fee or any taxes from it again."},"fees":{"type":["null","array"],"items":{"type":["null","object"],"properties":{"fee_structure":{"type":"string","description":"How the fee was computed (e.g. a fixed percentage or a volume-tiered rate)."},"fee_data":{"type":["null","object"],"properties":{"fee_type":{"type":"string","description":"Fee category (e.g. a transaction/spread fee)."},"fee_amount":{"type":["null","string"],"description":"Fee amount in the quote currency (USD)."},"fee_ratio":{"type":["null","string"],"description":"Rate this fee was computed at, when applicable."}},"description":"This fee's amount, type, and rate.","additionalProperties":false}},"additionalProperties":false},"description":"Itemized fee breakdown for exchange-routed orders. Empty or absent when the order carries no itemized fees."},"tax_withholding":{"type":["null","object"],"properties":{"withholding_rate":{"type":"string","description":"Withholding rate preformatted as a percent (e.g. '24%'), aggregated across the federal and any state portion. Print verbatim. Absent when no rate is available."},"estimated_withholding_amount":{"type":["null","string"],"description":"Estimated USD to be withheld from this sell's proceeds. Present only while cumulative_quantity is 0. Exactly one of this and total_withholding_amount is ever present, so read the one that is there."},"total_withholding_amount":{"type":["null","string"],"description":"Actual USD withheld from proceeds across fills so far (final once fully filled). Present only once cumulative_quantity is positive. Exactly one of this and estimated_withholding_amount is ever present, so read the one that is there."}},"description":