                          "description": "Crypto account number for this account (e.g. 'RHC1234567'). Absent when no linked crypto account exists. Mask all but the last 4 digits (e.g. '••••1234') when displaying to the user."
                        },
                        "type": {
                          "type": "string",
                          "description": "'cash', 'margin', or 'limited_margin' — the trading-permissions classification for the brokerage account. 'limited_margin' (instant settlement without full margin leverage) applies to accounts where full margin is unavailable, such as retirement (IRA), managed, and agentic accounts. Crypto accounts are never marginable, so a linked crypto account has no equivalent."
                        },
                        "unsettled_funds": {
                          "type": "string",
                          "description": "Proceeds from recent sales not yet settled (cash accounts settle T+1), in the account's currency. Informational only and may lag live trading — this is NOT a spendable or order-gating figure; buying_power from get_portfolio is authoritative for what can be traded now. A cash-type account with unsettled_funds greater than 0 could trade with those proceeds immediately by upgrading to limited margin. Absent when upstream does not report it — treat as unknown, not zero."
                        },
                        "brokerage_account_type": {
                          "type": "string",
                          "description": "Account type, e.g. 'individual', 'ira_traditional', 'ira_roth', 'ira_traditional_inherited', 'ira_roth_inherited', 'isa_stocks_and_shares'."
                        },
                        "nickname": {
                          "type": "string",
                          "description": "User-set nickname; present alongside account_number when set. Cosmetic only — not an agentic_allowed or agentic-account signal."
                        },
                        "is_default": {
                          "type": "boolean",
                          "description": "True for the user's default account. Surface when choosing among multiple accounts."
                        },
                        "agentic_allowed": {
                          "type": "boolean",
                          "description": "True when this account is accessible to this agent specifically. An account with false may be agentic-enabled but scoped to a different agent type — do not tell the user it is disabled. Sole source of truth for eligibility — never infer it from nickname text. review_*/place_*/cancel_* tools reject accounts where this is false."
                        },
                        "option_level": {
                          "type": "string",
                          "description": "Options approval: 'option_level_2' (long calls/puts, covered calls, cash-secured puts), 'option_level_3' (spreads and complex strategies), or empty/'option_level_0' (not approved)."
                        },
                        "management_type": {
                          "type": "string",
                          "description": "Management classification (e.g. 'managed') when applicable; layered on top of brokerage_account_type rather than replacing it."
                        },
                        "affiliate": {
                          "type": "string",
                          "description": "Affiliate / region code (e.g. 'RHF', 'RHUK', 'RHSG'). Affects feature availability for the account."
                        },
                        "state": {
                          "type": "string",
                          "description": "Account state — 'active' is normal; anything else (deactivated, restricted, etc.) means the account cannot trade normally."
                        },
                        "deactivated": {
                          "type": "boolean",
                          "description": "True when the account is currently deactivated."
                        },
                        "permanently_deactivated": {
                          "type": "boolean",
                          "description": "True when the account is permanently closed (cannot be reactivated)."
                        }
                      },
                      "required": [
                        "account_number",
                        "rhs_account_number",
                        "type",
                        "brokerage_account_type",
                        "is_default",
                        "agentic_allowed",
                        "option_level",
                        "state",
                        "deactivated",
                        "permanently_deactivated"
                      ],
                      "additionalProperties": false
                    },
                    "description": "The user's brokerage accounts. Empty when the user has none."
                  }
                },
                "description": "Tool-specific result payload; see the inner properties for fields.",
                "required": [
                  "accounts"
                ],
                "additionalProperties": false
              },
              "guide": {
                "type": "string",
                "description": "Sort the list deterministically when presenting: the default account first, agentic accounts (agentic_allowed=true) second, then other individual accounts, then retirement (IRA) accounts. Present account_number, rhc_account_number (label it \"Crypto Account\"), brokerage_account_type (label it \"Account Type\" — a linked crypto account always shares it, so never add a separate crypto account type column), type (label it \"Brokerage Trading Type\"), nickname (if set), and is_default — in that column order. In the Crypto Account column show \"N/A\" for accounts with an empty rhc_account_number; omit the column entirely only when no account has one. When referring to the account in user-facing prose (e.g. \"your <X> account\"), use nickname when set; fall back to brokerage_account_type otherwise. When displaying account_number or rhc_account_number to the user, mask all but the last 4 digits (e.g. '••••1234'); pass the full value to other tools unchanged — including get_option_level_upgrade_info and any fallback upgrade URL; masking breaks the link. Flag agentic_allowed when the user is choosing an account for a trade. There is exactly one agentic_allowed=true account — use it directly rather than asking which account to trade. agentic_allowed is caller-relative — true means accessible to this agent, false means this agent cannot act on it (the account may still be agentic-enabled for a different agent). Never state agentic_allowed's field name or raw boolean value to the user. Do not use nickname to determine agentic-account eligibility. Skip false accounts for trade operations; if the user asks why, say the account is not accessible to this agent, not that it needs to be enabled. When option_level is empty or 'option_level_0' and the user wants options, call get_option_level_upgrade_info with the account_number; if that tool is unavailable, direct the user to https://applink.robinhood.com/upgrade_options?account_number=<that account's account_number> (embed the full unmasked account_number in the URL). management_type='managed' is layered on brokerage_account_type — surface alongside, not as a replacement. For tools that ask for an account identifier on a crypto-backed flow (get_crypto_positions, future crypto write tools), pass rhs_account_number; for everything else (equities, options, etc.) pass account_number. Do not add an unsettled_funds column to the account table — surface it only via the following rule. Whenever you report an account's funds, value, or buying power and that account has type='cash' with unsettled_funds greater than 0, tell the user those unsettled proceeds could be traded immediately with a limited-margin upgrade, and — if the get_limited_margin_upgrade_info tool is available — call it with the account_number and share the appropriate upgrade link. If that tool is not available, say nothing about limited margin (there is no fallback). "
              }
            },
