      "get_crypto_account_onboarding_info": {
        "contract": {
          "name": "get_crypto_account_onboarding_info",
          "title": null,
          "description": "Get the link a user opens to sign the crypto agreement and open a crypto account. Call when the user wants to trade crypto but has no crypto account.",
          "input_schema": {
            "type": "object",
            "additionalProperties": false
          },
          "output_schema": {
            "type": "object",
            "properties": {
              "data": {
                "type": "object",
                "properties": {
                  "already_onboarded": {
                    "type": "boolean",
                    "description": "True when the user already has at least one crypto account — onboarding_url is empty and no signup is needed. False when they have none and should open the link to sign up."
                  },
                  "onboarding_url": {
                    "type": "string",
                    "description": "Link for the user to sign the crypto agreement and open a crypto account. The user must log in to their Robinhood account at the link to sign. Present it as a tappable link; never call it programmatically. Empty when already_onboarded is true."
                  }
                },
                "description": "Tool-specific result payload; see the inner properties for fields.",
                "required": [
                  "already_onboarded"
                ],
                "additionalProperties": false
              },
              "guide": {
                "type": "string",
                "description": "If already_onboarded is true, the user already has a crypto account, so no new signup is needed — do NOT present a link (the signup link cannot create or re-activate an account when one already exists). Tell them they already have a crypto account; do not claim it is active or ready to trade. If they say they still cannot trade crypto, their account may be deactivated, which is a separate reactivation flow this tool does not cover — direct them to Robinhood support rather than the link. Otherwise, send onboarding_url to the user as a tappable link, and tell them they must log in to their Robinhood account at the link to review and sign the crypto user agreement. After they sign, their crypto account(s) are provisioned — this tool does not create the account or sign on the user's behalf. Signing provisions crypto accounts for all of the user's eligible brokerage accounts, so a user who has an agentic brokerage account also gets an agentic crypto account. Once the user confirms they have finished, call get_accounts again with a fresh request to pick up the new crypto account before retrying; do not reuse a prior get_accounts result, as the account does not exist until the user completes this flow."
              }
            },
            "required": [
              "data",
              "guide"
            ],
            "additionalProperties": false
          },
          "annotations": {
            "readOnlyHint": true
          },
