                          "description": "Total notional filled so far in the quote currency, rounded to 2 decimals."
                        },
                        "executions": {
                          "type": [
                            "null",
                            "array"
                          ],
                          "items": {
                            "type": [
                              "null",
                              "object"
                            ],
                            "properties": {
                              "id": {
                                "type": "string",
                                "description": "Execution UUID."
                              },
                              "price": {
                                "type": "string",
                                "description": "Reported fill price per unit asset (e.g. USD per BTC). For the price the user actually paid after venue adjustments, use effective_price."
                              },
                              "effective_price": {
                                "type": "string",
                                "description": "Per-unit price after venue fees or price adjustments are applied — closer to the user's realized fill economics than price."
