                          "type": [
                            "null",
                            "string"
                          ],
                          "description": "Fee for this order in the quote currency (USD on USD-quoted pairs) — an estimate before any fill; once filled, the amount collected on fills so far (final when fully filled). Absent when the order carries no itemized fees (typical of Market Maker Routing) — treat absence as no fee data, not a $0 charge."
                        },
                        "fee_rate": {
                          "type": "string",
                          "description": "Rate this order's fee was computed at, preformatted: the bare percent on single-rate fee pricing (e.g. '0.95%'), suffixed with the liquidity outcome on maker/taker-priced accounts — e.g. '0.05% maker', '0.1% taker', or '0.07% blended' for orders filled partly maker and partly taker. Absent when no fee rate applies."
                        }
                      },
                      "required": [
                        "id",
                        "account_id",
                        "currency_pair_id",
                        "side",
                        "type",
                        "state",
                        "time_in_force",
                        "quantity",
                        "cumulative_quantity",
                        "created_at",
                        "updated_at"
                      ],
