      "get_earnings_calendar": {
        "contract": {
          "name": "get_earnings_calendar",
          "title": null,
          "description": "List earnings reports scheduled across the market over a date window (up to 31 days), optionally limited to high-market-cap names. Returns one entry per report event — estimated/actual EPS, report date and timing (am/pm), and company-verification status. Use this for market-wide discovery (\"what large-caps report this week?\"). For a specific known ticker, use get_earnings_results instead. Read-only.",
          "input_schema": {
            "type": "object",
            "properties": {
              "start_date": {
                "type": "string",
                "description": "Window anchor, YYYY-MM-DD. Defaults to today (US/Eastern) when omitted."
              },
              "days": {
                "type": "integer",
                "description": "Window length in days, measured from start_date. Defaults to 7. Positive = forward window (e.g. 7 = the next 7 days, inclusive of start_date); negative = look-back window (e.g. -7 = the 7 days ending at start_date). Must be a non-zero value between -31 and 31 — windows wider than 31 days are rejected."
              },
              "filter": {
                "type": "string",
                "description": "Optional result filter. Set to 'high_market_cap' to limit the calendar to high-market-cap names (market cap over $1B) — useful for 'what large-caps report this week' style questions. Omit for all names."
              }
            },
            "additionalProperties": false
          },
          "output_schema": {
            "type": "object",
            "properties": {
              "data": {
                "type": "object",
                "properties": {
                  "results": {
                    "type": [
                      "null",
                      "array"
                    ],
                    "items": {
                      "type": [
                        "null",
                        "object"
                      ],
                      "properties": {
                        "symbol": {
                          "type": "string",
                          "description": "Ticker symbol the earnings event belongs to."
                        },
                        "year": {
                          "type": "integer",
                          "description": "Fiscal year of the report (e.g. 2026)."
                        },
                        "quarter": {
                          "type": "integer",
                          "description": "Fiscal quarter of the report (1-4)."
                        },
                        "eps": {
                          "type": "object",
                          "properties": {
                            "estimate": {
                              "type": [
                                "null",
                                "string"
                              ],
                              "description": "Expected (estimated) EPS for the quarter. Null when no estimate is available for this quarter."
                            },
                            "actual": {
                              "type": [
                                "null",
                                "string"
                              ],
                              "description": "Reported EPS for the quarter. Null for upcoming quarters (not yet reported) — pair with report.date to tell the two apart."
                            }
                          },
                          "description": "Estimated and actual earnings per share for the quarter. Both sides may be null — see field docs.",
                          "required": [
                            "estimate",
                            "actual"
                          ],
                          "additionalProperties": false
                        },
                        "report": {
                          "type": [
                            "null",
                            "object"
                          ],
                          "properties": {
                            "date": {
                              "type": [
                                "null",
                                "string"
                              ],
                              "description": "YYYY-MM-DD report date. Present whenever the parent report block is non-null — use the parent's null/non-null state, not this field, to detect 'no scheduled event'."
                            },
                            "timing": {
                              "type": [
                                "null",
                                "string"
                              ],
                              "description": "'am' (before market) or 'pm' (after market). Null when timing is not yet known — only distinguishes before/after market, not an exact time."
                            },
                            "verified": {
                              "type": "boolean",
                              "description": "True when the company has confirmed the report date. False when the date is tentative (not yet company-confirmed)."
                            }
                          },
                          "description": "Report scheduling — date, am/pm timing, company-verification flag. Null when upstream has no scheduled event for this quarter yet.",
                          "required": [
