      "get_equity_historicals": {
        "contract": {
          "name": "get_equity_historicals",
          "title": null,
          "description": "Get OHLCV bars for one or more equity symbols across an explicit time range. Use this for charting, \"recent activity\" questions, and backtesting. The server auto-selects an interval when one is not provided. If the bar's interpolated field is true, bar was synthesized to fill a gap and carry no new information.\n\nParameter rules:\n- interval is optional; when omitted, the server auto-selects an interval that targets ~2,500 bars across the requested range. Provide an explicit interval only when you need a specific granularity.\n- interval values are fixed; the server does NOT aggregate intermediate bars. For a custom interval (e.g. 3-minute), request the next-finer fixed interval and aggregate client-side.\n- bounds defaults to 'regular' (RTH only). Use 'extended' or '24_5' only when the user explicitly asks about extended-hours activity.\n- adjustment_type defaults to 'split' (split-adjusted, the right default for backtesting). Use 'none' for raw prices, 'all' for split + dividend adjustment.\n- If the range would produce more bars than the upstream allows at the explicitly requested interval, narrow the range or coarsen the interval — the call is rejected before reaching upstream. The cap does not apply when interval is auto-selected.",
          "input_schema": {
            "type": "object",
            "properties": {
              "symbols": {
                "type": [
                  "null",
                  "array"
                ],
                "items": {
                  "type": "string"
                },
                "description": "One or more stock symbols (uppercase). Up to 10 per call."
              },
              "start_time": {
                "type": "string",
                "description": "Start of the range (RFC3339 UTC, e.g. '2026-01-01T00:00:00Z'). Required."
              },
              "end_time": {
                "type": "string",
                "description": "End of the range (RFC3339 UTC). Optional — when omitted, defaults to the current time."
              },
              "interval": {
                "type": "string",
                "description": "Bar interval. Optional — when omitted, the server picks an interval that targets ~2,500 bars across the requested range. Intraday: 15second, 30second, minute, 5minute, 10minute, 30minute, hour, 4hour. Interday: day, week, month, 3month, 6month, year, 5year, 10year, 20year, 50year. Note: the 1-minute bar is named 'minute' (not '1minute')."
              },
              "bounds": {
                "type": "string",
                "description": "Session bounds. One of 'regular' (RTH, default), 'extended', 'trading', '24_5', '24_7', 'hyper_trading'."
              },
              "adjustment_type": {
                "type": "string",
                "description": "Corporate-action adjustment: 'none' (raw prices), 'split' (default; right for backtesting), or 'all' (split + dividend; intraday only)."
              }
            },
            "required": [
              "symbols",
              "start_time"
            ],
            "additionalProperties": false
          },
          "output_schema": {
            "type": "object",
            "properties": {
              "data": {
                "type": "object",
                "properties": {
                  "results": {
                    "type": [
                      "null",
                      "array"
                    ],
                    "items": {
                      "type": "object",
                      "properties": {
                        "symbol": {
                          "type": "string",
                          "description": "Ticker symbol."
                        },
                        "interval": {
                          "type": "string",
                          "description": "Bar interval. Echoes the request when one was supplied; otherwise reports the server-auto-selected interval."
                        },
                        "bounds": {
                          "type": "string",
                          "description": "Session bounds echoed from the request."
                        },
                        "bars": {
                          "type": [
                            "null",
                            "array"
                          ],
                          "items": {
                            "type": [
                              "null",
                              "object"
                            ],
                            "properties": {
                              "begins_at": {
                                "type": "string",
                                "description": "Start of the bar (RFC3339 UTC). Bars are left-edge labeled."
                              },
                              "open_price": {
                                "type": "string",
                                "description": "First trade price in the bar."
                              },
                              "close_price": {
                                "type": "string",
                                "description": "Last trade price in the bar. NOT the official settled close; for that use get_equity_quotes closes[]."
                              },
                              "high_price": {
                                "type": "string",
                                "description": "Highest trade price in the bar."
                              },
                              "low_price": {
                                "type": "string",
                                "description": "Lowest trade price in the bar."
                              },
                              "volume": {
                                "type": "integer",
                                "description": "Share volume in the bar. Zero for interpolated bars."
                              },
                              "session": {
                                "type": "string",
                                "description": "Wire-format session: 'reg' (regular hours), 'pre' (pre-market), or 'post' (after-hours). Empty/absent when the bar's session is unknown."
                              },
                              "interpolated": {
                                "type": "boolean",
                                "description": "True when the bar was synthesized to fill a gap (no trades occurred). OHLC values are forward-filled from a nearby bar; volume is zero."
                              }
                            },
                            "required": [
                              "begins_at",
                              "open_price",
                              "close_price",
                              "high_price",
                              "low_price",
                              "volume"
                            ],
                            "additionalProperties": false
                          },
                          "description": "Bars in ascending time order. Empty if no trading activity in the window."
                        }
                      },
                      "required": [
                        "symbol",
                        "interval",
                        "bounds",
                        "bars"
                      ],
                      "additionalProperties": false
                    },
                    "description": "One entry per requested symbol that resolved upstream."
                  },
                  "not_found": {
                    "type": [
                      "null",
                      "array"
                    ],
                    "items": {
                      "type": "string"
                    },
                    "description": "Requested symbols that did not resolve (delisted, invalid, or non-equity). Absent when every requested symbol resolved."
                  }
                },
                "description": "Tool-specific result payload; see the inner properties for fields.",
                "required": [
                  "results"
                ],
                "additionalProperties": false
              },
              "guide": {
                "type": "string",
                "description": "Bars are left-edge labeled in UTC; convert to the user's timezone for presentation. Treat interpolated=true bars as gap-fill — they carry no new info and should usually be hidden in charts and ignored for analytics. close_price on the most recent bar is NOT the official settled close — use get_equity_quotes for that. For a multi-bar move, compute return from the first bar's open_price to the last bar's close_price; do not aggregate intermediate interpolated bars. When bounds='regular' the bar series covers only regular trading hours — gaps between trading sessions are not zero-filled, they are simply absent. When the request omitted interval, the 'interval' field on each result reports what the server auto-selected."
              }
            },
            "required": [
              "data",
              "guide"
            ],
            "additionalProperties": false
          },
          "annotations": {
            "readOnlyHint": true
          },
