              }
            },
            "required": [
              "symbols"
            ],
            "additionalProperties": false
          },
          "output_schema": {
            "type": "object",
            "properties": {
              "data": {
                "type": "object",
                "properties": {
                  "books": {
                    "type": [
                      "null",
                      "array"
                    ],
                    "items": {
                      "type": [
                        "null",
                        "object"
                      ],
                      "properties": {
                        "symbol": {
                          "type": "string",
                          "description": "Ticker symbol this book is for."
                        },
                        "updated_at": {
                          "type": "string",
                          "description": "Time the snapshot was taken."
                        },
                        "asks": {
                          "type": [
                            "null",
                            "array"
                          ],
                          "items": {
                            "type": "object",
                            "properties": {
                              "price": {
                                "type": "string",
                                "description": "Limit price at this level, as a decimal string."
                              },
                              "quantity": {
                                "type": "integer",
                                "description": "Aggregate shares resting at this price level."
                              }
                            },
                            "required": [
                              "price",
                              "quantity"
                            ],
                            "additionalProperties": false
                          },
                          "description": "Ask (sell-side) levels, ascending by price (best/lowest ask first). Empty when the book is unavailable."
                        },
                        "bids": {
                          "type": [
                            "null",
                            "array"
                          ],
                          "items": {
                            "type": "object",
                            "properties": {
                              "price": {
                                "type": "string",
                                "description": "Limit price at this level, as a decimal string."
                              },
                              "quantity": {
                                "type": "integer",
                                "description": "Aggregate shares resting at this price level."
                              }
                            },
                            "required": [
                              "price",
                              "quantity"
                            ],
                            "additionalProperties": false
                          },
                          "description": "Bid (buy-side) levels, descending by price (best/highest bid first). Empty when the book is unavailable."
                        }
                      },
                      "required": [
                        "symbol",
                        "updated_at",
                        "asks",
                        "bids"
                      ],
                      "additionalProperties": false
                    },
                    "description": "One order-book snapshot per successfully fetched symbol, in request order. A symbol that failed appears in errors instead."
