          "name": "get_equity_technical_indicators",
          "title": null,
          "description": "Compute a technical indicator (RSI, MACD, Bollinger Bands, moving averages, ATR, VWAP, and more) over one equity symbol's OHLCV bars across a time range. For the raw OHLCV bars themselves, use get_equity_historicals.\n\nParameter rules:\n- The parameters an indicator accepts depend on type:\n  - period only: ema/sma (default 9); rsi/cci/atr/mfi (default 14); williams_r/adx (default 10); momentum (default 12); roc (default 14); donchian_channels (default 20).\n  - bollinger_bands: period (default 20) + num_std (default 2).\n  - macd: fast_period (12), slow_period (26), signal_period (9).\n  - keltner_channels: period (default 20) + multiplier (default 2).\n  - supertrend: period (default 10) + multiplier (default 3).\n  - pivot_points: method (only 'classic').\n  - vwap, obv: no parameters.\n  Omit a parameter to use its default. Passing a parameter the chosen type does not accept is rejected.\n- interval is REQUIRED — indicator periods are counted in bars, so there is no auto-selection.\n- adjustment_type defaults to 'split'; 'all' (split + dividend) requires a day-or-coarser interval.\n- If the requested range plus the indicator's warm-up exceeds the per-request bar cap, narrow the range or coarsen the interval.",
          "input_schema": {
            "type": "object",
            "properties": {
              "symbol": {
                "type": "string",
                "description": "Stock symbol (uppercase). Exactly one symbol per call."
              },
              "type": {
                "type": "string",
                "description": "Indicator to compute. One of: ema, sma, rsi, momentum, roc, cci, williams_r, atr, mfi, adx, donchian_channels, bollinger_bands, macd, keltner_channels, supertrend, vwap, obv, pivot_points."
              },
              "interval": {
                "type": "string",
                "description": "Required bar interval the indicator is computed on. Intraday: 15second, 30second, minute, 5minute, 10minute, 30minute, hour, 4hour. Interday: day, week, month, 3month, 6month, year, 5year, 10year, 20year, 50year. The 1-minute bar is named 'minute' (not '1minute')."
              },
              "start_time": {
                "type": "string",
                "description": "Start of the range (RFC3339 UTC, e.g. '2026-01-01T00:00:00Z'). Required."
              },
              "end_time": {
                "type": "string",
                "description": "End of the range (RFC3339 UTC). Optional — defaults to the current time when omitted."
              },
              "bounds": {
                "type": "string",
                "description": "Session bounds. One of 'regular' (RTH, default) or 'extended'."
              },
              "adjustment_type": {
                "type": "string",
                "description": "Corporate-action adjustment: 'none' (raw prices), 'split' (default), or 'all' (split + dividend; requires a day-or-coarser interval)."
              },
              "output": {
                "type": "string",
                "description": "How much of the series to return: 'series' (default, full range), 'latest' (most recent bar only), or 'last:N' (most recent N bars). The indicator is always computed over the full range first; this only trims the response."
              },
              "period": {
                "type": [
                  "null",
                  "integer"
                ],
                "description": "Lookback period in bars. Applies to ema, sma, rsi, momentum, roc, cci, williams_r, atr, mfi, adx, donchian_channels, bollinger_bands, keltner_channels, supertrend. Omit to use the indicator's default."
              },
              "num_std": {
                "type": [
                  "null",
                  "number"
                ],
                "description": "Number of standard deviations for the bands. bollinger_bands only (default 2)."
              },
              "fast_period": {
                "type": [
                  "null",
                  "integer"
                ],
                "description": "Fast EMA period. macd only (default 12)."
              },
              "slow_period": {
                "type": [
                  "null",
                  "integer"
                ],
                "description": "Slow EMA period. macd only (default 26)."
              },
              "signal_period": {
                "type": [
                  "null",
                  "integer"
                ],
                "description": "Signal EMA period. macd only (default 9)."
              },
              "multiplier": {
                "type": [
                  "null",
                  "number"
                ],
                "description": "Band/offset multiplier. keltner_channels (default 2) and supertrend (default 3) only."
              },
              "method": {
                "type": "string",
                "description": "Calculation method. pivot_points only; currently only 'classic'."
              }
            },
            "required": [
              "symbol",
              "type",
              "interval",
              "start_time"
            ],
            "additionalProperties": false
          },
          "output_schema": {
            "type": "object",
            "properties": {
              "data": {
                "type": "object",
                "properties": {
                  "symbol": {
                    "type": "string",
                    "description": "Ticker symbol echoed from the request."
                  },
                  "interval": {
                    "type": "string",
                    "description": "Bar interval the indicator was computed on, echoed from the request."
                  },
                  "bounds": {
                    "type": "string",
                    "description": "Session bounds echoed from the request."
                  },
                  "indicators": {
                    "type": [
                      "null",
                      "array"
                    ],
                    "items": {
                      "type": [
                        "null",
                        "object"
                      ],
                      "properties": {
                        "type": {
                          "type": "string",
                          "description": "Indicator type, e.g. 'rsi', 'macd', 'bollinger_bands'."
                        },
                        "params": {
                          "type": "object",
                          "description": "Numeric parameters actually used after defaults were applied, e.g. {\"period\":14} or {\"fast_period\":12,\"slow_period\":26,\"signal_period\":9}.",
                          "additionalProperties": {
                            "type": "number"
                          }
                        },
                        "series": {
                          "type": [
                            "null",
                            "array"
                          ],
                          "items": {
                            "type": [
                              "null",
                              "object"
                            ],
                            "properties": {
                              "begins_at": {
                                "type": "string",
                                "description": "Bar start timestamp (RFC3339 UTC), left-edge labeled."
                              }
                            },
                            "description": "One bar of indicator output: 'begins_at' plus one or more numeric output fields whose names depend on the indicator type — 'value' for single-output indicators; 'upper'/'middle'/'lower' for bollinger_bands and channel indicators; 'macd'/'signal'/'histogram' for macd. A field is null when the value is undefined for that bar."
                          },
                          "description": "Output bars in ascending time order, after the warm-up region is dropped. Trimmed per the request's output mode (full series, the latest bar, or the last N)."
                        }
                      },
                      "required": [
                        "type",
                        "params",
                        "series"
                      ],
                      "additionalProperties": false
                    },
                    "description": "Computed indicators. Exactly one entry (one indicator per request)."
                  }
                },
                "description": "Tool-specific result payload; see the inner properties for fields.",
                "required": [
                  "symbol",
                  "interval",
                  "bounds",
                  "indicators"
                ],
                "additionalProperties": false
              },
              "guide": {
                "type": "string",
                "description": "Convert begins_at (UTC) to the user's timezone for display. Skip a null output field rather than presenting it as zero. When an indicator emits multiple output fields per bar (e.g. bollinger_bands, macd), interpret them together, not in isolation."
              }
            },
            "required": [
              "data",
              "guide"
            ],
            "additionalProperties": false
          },
          "annotations": {
            "readOnlyHint": true
          },
