                          "type": [
                            "null",
                            "array"
                          ],
                          "items": {
                            "type": "object",
                            "properties": {
                              "account_type": {
                                "type": "string",
                                "description": "Brokerage account type (e.g. 'individual', 'ira_traditional', 'ira_roth')."
                              },
                              "account_type_tradability": {
                                "type": "string",
                                "description": "'tradable', 'untradable', or 'position_closing_only' (sell-only)."
