      "get_financials": {
        "contract": {
          "name": "get_financials",
          "title": null,
          "description": "Get a company's reported financial metrics over time — revenue, gross profit, net income, and net margin — by fiscal period (annual or quarterly), for one or more symbols. Use this for fundamental analysis like revenue-growth and margin-trend tracking, profitability screens, and period-over-period comparisons. Read-only.",
          "input_schema": {
            "type": "object",
            "properties": {
              "symbols": {
                "type": [
                  "null",
                  "array"
                ],
                "items": {
                  "type": "string"
                },
                "description": "One or more stock symbols (max 20 per call). Exact-ticker match — no name or partial-ticker resolution. Lowercase and whitespace-padded input is normalized to uppercase-trimmed before forwarding."
              },
              "period": {
                "type": "string",
                "description": "Reporting period: 'quarterly' or 'annual'. Defaults to 'quarterly' when omitted."
              },
              "limit": {
                "type": "integer",
                "description": "Number of most-recent periods to return per symbol (e.g. 8 for the last 8 quarters or years). Defaults to 4; values above 40 are capped to 40."
              }
            },
            "required": [
              "symbols"
            ],
            "additionalProperties": false
          },
          "output_schema": {
            "type": "object",
            "properties": {
              "data": {
                "type": "object",
                "properties": {
                  "results": {
                    "type": [
                      "null",
                      "array"
                    ],
                    "items": {
                      "type": [
                        "null",
                        "object"
                      ],
                      "properties": {
                        "symbol": {
                          "type": "string",
                          "description": "The requested ticker, in canonical uppercase form."
                        },
                        "period": {
                          "type": "string",
                          "description": "Echo of the reporting period for this entry: 'quarterly' or 'annual'."
                        },
                        "financials": {
                          "type": [
                            "null",
                            "array"
                          ],
                          "items": {
                            "type": [
                              "null",
                              "object"
                            ],
                            "properties": {
                              "fiscal_year": {
                                "type": "integer",
                                "description": "Fiscal year of the reporting period (e.g. 2026)."
                              },
                              "fiscal_quarter": {
                                "type": [
                                  "null",
                                  "integer"
                                ],
                                "description": "Fiscal quarter (1-4) for quarterly periods. Null for annual periods — use it to tell the two apart."
                              },
                              "period_end_date": {
                                "type": "string",
                                "description": "Fiscal period end date, YYYY-MM-DD."
                              },
                              "revenue": {
                                "type": [
                                  "null",
                                  "string"
                                ],
                                "description": "Total revenue for the period, as a decimal string. Null when unavailable for the period — present as 'not available', not zero."
                              },
                              "gross_profit": {
                                "type": [
                                  "null",
                                  "string"
                                ],
                                "description": "Gross profit (revenue minus cost of goods sold) for the period, as a decimal string. Null when unavailable."
                              },
                              "net_income": {
                                "type": [
                                  "null",
                                  "string"
                                ],
                                "description": "Bottom-line net income for the period, as a decimal string. Null when unavailable."
                              },
                              "net_margin": {
                                "type": [
                                  "null",
                                  "string"
                                ],
                                "description": "Net margin (net income divided by revenue) for the period, expressed as a percentage (e.g. 12.34 means 12.34%). Null when unavailable."
                              }
                            },
                            "required": [
                              "fiscal_year",
                              "fiscal_quarter",
                              "period_end_date",
                              "revenue",
                              "gross_profit",
                              "net_income",
                              "net_margin"
                            ],
                            "additionalProperties": false
                          },
                          "description": "Reporting periods, most recent first, up to the requested limit. Fewer than the limit when less history is available."
                        }
                      },
                      "required": [
                        "symbol",
                        "period",
                        "financials"
                      ],
                      "additionalProperties": false
                    },
                    "description": "Per-symbol financials, positionally aligned to the requested symbols (same order). A null entry means that symbol could not be resolved or has no reported financials."
                  }
                },
                "description": "Tool-specific result payload; see the inner properties for fields.",
                "required": [
                  "results"
                ],
                "additionalProperties": false
              },
              "guide": {
                "type": "string",
                "description": "results is positional — aligned one-to-one with the requested symbols, in order. A null entry means that symbol could not be resolved (invalid, delisted, or non-equity) or has no reported financials available; surface it as \"no data for X\" rather than dropping it silently. Within an entry, financials is most-recent-first. Tell quarterly from annual rows by fiscal_quarter (null for annual). Present null metric values as \"not available\", not zero. net_margin is already a percentage — do not multiply by 100."
              }
            },
            "required": [
              "data",
              "guide"
            ],
            "additionalProperties": false
          },
