      "get_limited_margin_upgrade_info": {
        "contract": {
          "name": "get_limited_margin_upgrade_info",
          "title": null,
          "description": "Check whether a cash account is eligible to upgrade to limited margin and return the links (web and mobile) that start the upgrade flow. Limited margin lets the account trade with unsettled funds — proceeds from a sale can go into a new order before that sale settles — while adding no borrowing or leverage. Call when the user asks about that capability, about trading with unsettled funds, or about enabling limited margin — or when a cash account shows unsettled_funds greater than 0 while you are reporting its funds, value, or buying power (the get_accounts and get_portfolio guides direct this)..",
          "input_schema": {
            "type": "object",
            "properties": {
              "account_number": {
                "type": "string",
                "description": "Brokerage account number to check. Obtain from get_accounts."
              }
            },
            "required": [
              "account_number"
            ],
            "additionalProperties": false
          },
          "output_schema": {
            "type": "object",
            "properties": {
              "data": {
                "type": "object",
                "properties": {
                  "account_number": {
                    "type": "string",
                    "description": "The account checked."
                  },
                  "eligible": {
                    "type": "boolean",
                    "description": "True when this account is a cash account that can be upgraded to limited margin."
                  },
                  "current_account_type": {
                    "type": "string",
                    "description": "The account's current type — 'cash', 'limited_margin', or 'unknown' if the type is unrecognized. An account already on 'limited_margin' returns eligible=false, since no upgrade is needed."
                  },
                  "web_upgrade_url": {
                    "type": "string",
                    "description": "Upgrade-flow link for desktop/web browsers (opens robinhood.com in the browser). Present only when eligible=true. Send exactly as returned with the account number unmasked — masking it breaks the link."
                  },
                  "mobile_upgrade_url": {
                    "type": "string",
                    "description": "Upgrade-flow link for mobile — a universal link that opens the flow in the Robinhood app. Present only when eligible=true. Send exactly as returned with the account number unmasked — masking it breaks the link."
                  },
                  "upgrade_fallback": {
                    "type": "string",
                    "description": "Instructions for reaching the upgrade flow manually when neither link opens. Present only when eligible=true."
                  }
                },
                "description": "Tool-specific result payload; see the inner properties for fields.",
                "required": [
                  "account_number",
                  "eligible",
                  "current_account_type"
                ],
                "additionalProperties": false
              },
              "guide": {
                "type": "string",
                "description": "When eligible=true, tell the user in one line what limited margin gives them: it lets the account trade with unsettled funds — proceeds from a closing order can go straight into a new order before that sale settles — with no borrowing or leverage. Then give the upgrade link that matches the user's device, introduced with a line like \"To upgrade your <nickname> account (••••<last4>), open this link:\" — send mobile_upgrade_url when the user is on a phone (a universal link that opens the flow in the Robinhood app) and web_upgrade_url when they are on desktop/web (opens in a browser). If the device is unknown, offer both, clearly labeled \"on your phone\" vs \"on desktop/web\". Name the account by its nickname and last four digits (from get_accounts) in the prose, but send the chosen URL exactly as returned with the account number unmasked (masking the number in the link breaks it). If the user reports that neither link works, give them the manual path from upgrade_fallback. The user completes the upgrade themselves in that flow (identity verification and agreement acceptance); this tool never changes the account, so once they confirm they finished, re-fetch get_accounts because the account type from any earlier call is now stale."
              }
            },
            "required": [
              "data",
              "guide"
            ],
            "additionalProperties": false
          },
          "annotations": {
            "readOnlyHint": true
          },
