ct that is already on the list is a no-op."}},"required":["data","guide"],"additionalProperties":false},"annotations":null,"execution":null,"shape_hash":"sha256:541e04c6acf5f6d49cc55a54baa3753cfa56bdabec264e9be4f4c2d496e3b0cf","contract_hash":"sha256:f459644f645b07d902e66d59a48d74d7e3fafc173b5ebb2633039996012ab1e2"},"category":null,"arguments":{},"result":{},"reason":"Options and watchlists are outside this broker profile’s scope.","warnings":[],"original":{"name":"add_option_to_watchlist","category":null,"arguments":{},"result":{},"reason":"Options and watchlists are outside this broker profile’s scope.","warnings":[]},"edits":[]},"add_to_watchlist":{"contract":{"name":"add_to_watchlist","title":null,"description":"Add items to a watchlist. Exactly one of symbols (stocks/ETFs), currency_pair_ids (crypto), or index_ids (market indexes like SPX, NDX) is required — mutually exclusive. For options use add_option_to_watchlist (separate dedicated watchlist). Futures still require the Robinhood app. Already-present items are no-ops. Confirm with the user before calling.","input_schema":{"type":"object","properties":{"list_id":{"type":"string","description":"UUID of the watchlist to add items to."},"symbols":{"type":["null","array"],"items":{"type":"string"},"description":"Stock symbols to add (e.g. ['AAPL', 'NVDA']). US stocks and ETFs only. Mutually exclusive with currency_pair_ids and index_ids."},"currency_pair_ids":{"type":["null","array"],"items":{"type":"string"},"description":"Currency-pair UUIDs to add (e.g. the object_id from get_watchlist_items where object_type=currency_pair, or the id from get_currency_pairs). Mutually exclusive with symbols and index_ids."},"index_ids":{"type":["null","array"],"items":{"type":"string"},"description":"Market-index UUIDs to add (the id field from get_indexes; SPX, NDX, DJI, etc.). Mutually exclusive with symbols and currency_pair_ids."}},"required":["list_id"],"additionalProperties":false},"output_schema":{"type":"object","properties":{"data":{"type":"object","properties":{"symbols":{"type":["null","array"],"items":{"type":"string"},"description":"The stock symbols this call targeted (instrument path)."},"currency_pair_ids":{"type":["null","array"],"items":{"type":"string"},"description":"The currency-pair UUIDs this call targeted (crypto path)."},"index_ids":{"type":["null","array"],"items":{"type":"string"},"description":"The index UUIDs this call targeted (index path)."},"object_type":{"type":"string","description":"'instrument' when symbols were used, 'currency_pair' when currency_pair_ids were used, 'index' when index_ids were used."},"list_id":{"type":"string","description":"The watchlist this call targeted."},"operation":{"type":"string","description":"'create' for add_to_watchlist, 'delete' for remove_from_watchlist."},"status":{"type":"string","description":"'ok' when the upstream accepted the operation."}},"description":"Tool-specific result payload; see the inner properties for fields.","required":["object_type","list_id","operation","status"],"additionalProperties":false},"guide":{"type":"string","description":"On success the response echoes the operations applied. 400 with 'invalid instrument id' means a symbol could not be resolved — confirm spelling with the user. 404 means the list_id is not writable by the user (likely a curated list; use a custom list instead). 400 with an allowed_object_types message means the target list does not accept this asset type — check the list's allowed_object_types in get_watchlists."}},"required":["data","guide"],"additionalProperties":false},"annotations":null,"execution":null,"shape_hash":"sha256:e49331b1434f96eae9b7f02c390489c12d4ad74368d2caa166f969c37980a73a","contract_hash":"sha256:0a28f5f94d12c1497f941ac0b8eaf69a947e502665456835545876669024e093"},"category":null,"arguments":{},"result":{},"reason":"Watchlists are outside this broker profile’s scope.","warnings":[],"original":{"name":"add_to_watchlist","category":null,"arguments":{},"re