,"annotations":{"readOnlyHint":true},"execution":null,"shape_hash":"sha256:2a6ef41432b84cdb5d3265199e9b91b0f271ee6aed19de4cbb2a43fccd8a5037","contract_hash":"sha256:40b28a44b2ae0c5f3e8bf87a40ecc43d59c64a575d9694a380fd8dec7bc3d6ed"},"category":"read.orders","arguments":{"account_number":"{account_id}"},"result":{"items":"data.orders","account":"{account_id}","order_id":"id"},"reason":"This lists equity orders belonging to the specified brokerage account.","warnings":[],"original":{"name":"get_equity_orders","category":"read.orders","arguments":{"account_number":"{account_id}"},"result":{"items":"data.orders","account":"{account_id}","order_id":"id"},"reason":"This lists equity orders belonging to the specified brokerage account.","warnings":[]},"edits":[]},"get_equity_positions":{"contract":{"name":"get_equity_positions","title":null,"description":"List open equity positions for a specific brokerage account. Returns symbol, quantity, average cost, and per-position hold breakdowns.","input_schema":{"type":"object","properties":{"account_number":{"type":"string","description":"Brokerage account number. Must come from the user or be clearly implied — never default from get_accounts."},"cursor":{"type":"string","description":"Pagination cursor. Omit for the first page; for the next page, pass the cursor query param from the prior response's next URL."}},"required":["account_number"],"additionalProperties":false},"output_schema":{"type":"object","properties":{"data":{"type":"object","properties":{"positions":{"type":["null","array"],"items":{"type":["null","object"],"properties":{"symbol":{"type":"string","description":"Ticker symbol."},"quantity":{"type":"string","description":"Total shares held, including today's fills. Negative for short positions."},"intraday_quantity":{"type":"string","description":"Portion of quantity filled today (upstream is timezone-aware)."},"average_buy_price":{"type":["null","string"],"description":"Average cost per share as shown in the Robinhood app; reflects partial sells. Omitted for positions still reconciling."},"shares_available_for_sells":{"type":"string","description":"Shares the user can sell right now (server-computed after subtracting holds)."},"shares_held_for_sells":{"type":"string","description":"Shares locked by open outgoing sell orders."},"shares_held_for_stock_grants":{"type":"string","description":"Shares held for settlement of stock grants / unsettled inbound fills."},"shares_held_for_options_events":{"type":"string","description":"Shares earmarked for an upcoming options exercise/assignment."},"shares_held_for_asset_transfer":{"type":"string","description":"Shares locked by an outgoing asset transfer (e.g. ACATS-out)."},"shares_pending_from_options_events":{"type":"string","description":"Shares pending from an options exercise/assignment, not yet booked into quantity."},"type":{"type":"string","description":"'long' (positive quantity), 'short' (negative), 'boxed' (both, rare), or 'empty' (zero)."}},"required":["symbol","quantity","intraday_quantity","shares_available_for_sells","shares_held_for_sells","shares_held_for_stock_grants","shares_held_for_options_events","shares_held_for_asset_transfer","shares_pending_from_options_events","type"],"additionalProperties":false},"description":"Open equity positions on this page. Empty when the cursor has no rows."},"next":{"type":"string","description":"Next-page URL. Empty when there are no more pages."}},"description":"Tool-specific result payload; see the inner properties for fields.","required":["positions"],"additionalProperties":false},"guide":{"type":"string","description":"Sellable shares: use shares_available_for_sells, not quantity. Yesterday's quantity = quantity - intraday_quantity. average_buy_price is the average cost per share shown in the Robinhood app (it already reflects partial sells) — use it as the user's average cost; it may be omitted for positions still reconciling. No market price here — for current value or PnL, call get_equity_quotes and multiply by quantity. Present symbol, quantity, average_buy_price, and type when not 'long'; suppress other fields unless asked."}},"required":["data","guide"],"additionalProperties":false},"annotations":{"readOnlyHint":true},"execution":null,"shape_hash":"sha256:64cbb88de2f69fc50a91fc7cb02a8a30393f7cc3b52a5a13e5d0fa74a9e7c804","contract_hash":"sha256:ca5fd9db46ae45fdf03cbc896bea9ca995a90e7ffa787f0908567b22d2c6f0b6"},"category":"read.positions","arguments":{"account_number":"{account_id}"},"result":{"items":"data.positions","account":"{account_id}","symbol":"symbol","quantity":"quantity","average_cost":"average_buy_price"},"reason":"This lists equity positions with symbol, quantity, and broker-reported average cost for the specified account.","warnings":[],"original":{"name":"get_equity_positions","category":"read.positions","arguments":{"account_number":"{account_id}"},"result":{"items":"data.positions","account":"{account_id}","symbol":"symbol","quantity":"quantity","average_cost":"average_buy_price"},"reason":"This lists equity positions with symbol, quantity, and broker-reported average cost for the specified account.","warnings":[]},"edits":[]},"get_equity_price_book":{"contract":{"name":"get_equity_price_book","title":null,"description":"Get a real-time bid/ask order book (Level 2) snapshot for one or more equity symbols (max 4), showing the ladder of price levels and resting share size on each side. Use to read supply/demand depth before entering or exiting a position.","input_schema":{"type":"object","properties":{"symbols":{"type":["null","array"],"items":{"type":"string"},"description":"One or more stock symbols, max 4 per call."}},"required":["symbols"],"additionalProperties":false},"output_schema":{"type":"object","properties":{"data":{"type":"object","properties":{"books":{"type":["null","array"],"items":{"type":["null","object"],"properties":{"symbol":{"type":"string","description":"Ticker symbol this book is for."},"updated_at":{"type":"string","description":"Time the snapshot was taken."},"asks":{"type":["null","array"],"items":{"type":"object","properties":{"price":{"type":"string","description":"Limit price at this level, as a decimal string."},"quantity":{"type":"integer","description":"Aggregate shares resting at this price level."}},"required":["price","quantity"],"additionalProperties":false},"description":"Ask (sell-side) levels, ascending by price (best/lowest ask first). Empty when the book is unavailable."},"bids":{"type":["null","array"],"items":{"type":"object","properties":{"price":{"type":"string","description":"Limit price at this level, as a decimal string."},"quantity":{"type":"integer","description":"Aggregate shares resting at this price level."}},"required":["price","quantity"],"additionalProperties":false},"description":"Bid (buy-side) levels, descending by price (best/highest bid first). Empty when the book is unavailable."}},"required":["symbol","updated_at","asks","bids"],"additionalProperties":false},"description":"One order-book snapshot per successfully fetched symbol, in request order. A symbol that failed appears in errors instead."},"errors":{"type":["null","array"],"items":{"type":"object","properties":{"symbol":{"type":"string","description":"Requested symbol that could not be returned."},"error":{"type":"string","description":"Why this symbol's book is unavailable: it did not resolve to an equity, the market is closed, or the snapshot request failed."}},"required":["symbol","error"],"additionalProperties":false},"description":"Per-symbol failures. A symbol appears here or in books, never both. Empty when every requested symbol succeeded."}},"description":"Tool-specific result payload; see the inner properties for fields.","required":["books"],"additionalProperties":false},"guide":{"type":"string","description":"Each book in books is one symbol's snapshot: asks are sell-side levels (lowest/best ask first) and bids are buy-side levels (highest/best bid first), so the inside market is asks[0] vs bids[0]. quantity is the resting share size at a level — a level with outsized size relative to its neighbors is a wall (support on the bid side, resistance on the ask side). A requested symbol appears in books OR in errors, never both: surface anything in errors (a symbol that did not resolve to an equity, or whose book was unavailable because the market is closed) rather than implying its book was empty. An empty asks or bids array means no resting liquidity on that side right now, not an error."}},"required":["data","guide"],"additionalProperties":false},"annotations":{"readOnlyHint":true},"execution":null,"shape_hash":"sha256:9377f1a5b164117f90c7a2e8a48afabf7a907414b74c6a007b02b6bde8163cc3","contract_hash":"sha256:5fdae13477f6658de454e26c5fc6189ca4d22d88e45a58041c4db601df2d8470"},"category":null,"arguments":{},"result":{},"reason":"Level 2 order-book data has no matching callable category in this profile.","warnings":[],"original":{"name":"get_equity_price_book","category":null,"arguments":{},"result":{},"reason":"Level 2 order-book data has no matching callable category in this profile.","warnings":[]},"edits":[]},"get_equity_quotes":{"contract":{"name":"get_equity_quotes","title":null,"description":"Get real-time stock quotes and the official last-completed-session close for one or more symbols.","input_schema":{"type":"object","properties":{"symbols":{"type":["null","array"],"items":{"type":"string"},"description":"One or more stock symbols. Above 20 symbols, quotes still return but closes is omitted with closes_error set."}},"required":["symbols"],"additionalProperties":false},"output_schema":{"type":"object","properties":{"data":{"type":"object","properties":{"results":{"type":["null","array"],"items":{"type":["null","object"],"properties":{"quote":{"type":["null","object"],"properties":{"symbol":{"type":"string","description":"Ticker symbol."},"last_trade_price":{"type":"string","description":"Most recent regular-hours trade (9:30-16:00 ET). Stays frozen at the closing print after the close until the next open; not the official settled close."},"venue_last_trade_time":{"type":"string","description":"Timestamp of last_trade_price."},"last_non_reg_trade_price":{"type":["null","string"],"description":"Most recent pre-market / after-hours / overnight trade. Null during regular hours or when the symbol does not trade in the current session."},"venue_last_non_reg_trade_time":{"type":["null","string"],"description":"Timestamp of last_non_reg_trade_price. Reveals which non-regular session the trade came from."},"adjusted_previous_close":{"type":"string","description":"Prior-day close adjusted for splits, dividends, and mergers."},"previous_close":{"type":"string","description":"Raw prior closing print — not corporate-action adjusted and not the official settled close."},"previous_close_date":{"type":["null","string"],"description":"YYYY-MM-DD trading date that previous_close corresponds to. Null for symbols that have never had a settled close."},"bid_price":{"type":"string","description":"Highest current buy-order price. Zero when the book is closed or unavailable."},"venue_bid_time":{"type":"string","description":"Timestamp of bid_price."},"ask_price":{"type":"string","description":"Lowest current sell-order price. Zero when the book is closed or unavailable."},"venue_ask_time":{"type":"string","description":"Timestamp of ask_price."},"has_traded":{"type":"boolean","description":"False for instruments that have never traded; price fields are meaningless when false."},"state":{"type":"string","description":"Instrument listing state — 'active' is normal; other values (inactive, delisted, unlisted) mean the instrument is not in normal trading state."}},"description":"Live market data for this symbol.","required":["symbol","last_trade_price","venue_last_trade_time","last_non_reg_trade_price","venue_last_non_reg_trade_time","adjusted_previous_close","previous_close","previous_close_date","bid_price","venue_bid_time","ask_price","venue_ask_time","has_traded","state"],"additionalProperties":false},"close":{"type":["null","object"],"properties":{"symbol":{"type":"string","description":"Ticker symbol."},"date":{"type":["null","string"],"description":"YYYY-MM-DD trading date for this close. May be earlier than the requested date when interpolated."},"price":{"type":["null","string"],"description":"Official settled close price. Null when the upstream has no close (rare)."},"interpolated":{"type":["null","boolean"],"description":"True when the requested date had no session and the price came from an earlier date."},"source":{"type":["null","string"],"description":"Upstream provenance (e.g. 'sip-close'). Informational."}},"description":"Official settled close from the most recent completed session. Absent when closes_error is set, or when this symbol had no close in an otherwise-successful closes batch.","required":["symbol","date","price","interpolated","source"],"additionalProperties":false}},"required":["quote"],"additionalProperties":false},"description":"One entry per symbol resolved from /quotes/, in upstream order, each carrying the live quote and (when available) the official prior-session close. Empty if no symbol resolved."},"closes_error":{"type":"string","description":"Populated when the closes lookup is skipped or fails tool-wide (e.g. too many symbols, upstream timeout, no previous_close_date). Per-symbol gaps surface as a missing close on the affected result, not here."}},"description":"Tool-specific result payload; see the inner properties for fields.","required":["results"],"additionalProperties":false},"guide":{"type":"string","description":"Each entry in results pairs the live quote with the official prior-session close for the same symbol. Current price: pick whichever of quote.last_trade_price / quote.last_non_reg_trade_price has the more recent timestamp, then verify that timestamp is recent before calling it "current" — otherwise phrase as "as of <time>". Daily change uses quote.adjusted_previous_close. "Yesterday's close" uses results[].close.price (official settled close); when a result is missing close — either closes_error is set tool-wide, or this symbol had no close in an otherwise-successful batch — fall back to quote.previous_close and tell the user the official close lookup is unavailable. Drop bid/ask when zero. Surface has_traded=false or any non-'active' state before quoting a price."}},"required":["data","guide"],"additionalProperties":false},"annotations":{"readOnlyHint":true},"execution":null,"shape_hash":"sha256:e1e6307375abb81ffb9369838c5f11ff0b7496a9046ef1eac6ad966e9206d14e","contract_hash":"sha256:6f95cbc71da8958b9d2f8e3864fe50b327bba74e393ab4378999ea1fe1f9795c"},"category":"read.quote","arguments":{"symbols":["{symbol}"]},"result":{"price":"data.results.0.quote.last_trade_price","asof":"data.results.0.quote.venue_last_trade_time"},"reason":"This reads a current equity price and its timezone-aware market timestamp for one symbol.","warnings":[],"original":{"name":"get_equity_quotes","category":"read.quote","arguments":{"symbols":["{symbol}"]},"result":{"price":"data.results.0.quote.last_trade_price","asof":"data.results.0.quote.venue_last_trade_time"},"reason":"This reads a current equity price and its timezone-aware market timestamp for one symbol.","warnings":[]},"edits":[]},"get_equity_tax_lots":{"contract":{"name":"get_equity_tax_lots","title":null,"description":"List the open tax lots for one equity holding in an account — each lot is a separate acquisition with its own quantity, cost basis, acquisition date, and long/short-term status. Requires a symbol (tax lots are tracked per instrument). Use it for cost-basis, holding-period, or which-lots-would-sell questions.","input_schema":{"type":"object","properties":{"account_number":{"type":"string","description":"Brokerage account number. Must come from the user or be clearly implied — never default from get_accounts."},"symbol":{"type":"string","description":"Ticker symbol of the holding whose tax lots you want, e.g. AAPL. Tax lots are tracked per instrument — one symbol per call."},"cursor":{"type":"string","description":"Pagination cursor. Omit for the first page; for the next page, pass the cursor query param from the prior response's next URL."}},"required":["account_number","symbol"],"additionalProperties":false},"output_schema":{"type":"object","properties":{"data":{"type":"object","properties":{"symbol":{"type":"string","description":"Echoed symbol these tax lots belong to."},"tax_lots":{"type":["null","array"],"items":{"type":["null","object"],"properties":{"open_lot_id":{"type":"string","description":"UUID identifying this open tax lot."},"open_tran_type":{"type":"string","description":"How the lot was acquired (e.g. a buy or transfer transaction type)."},"order_id":{"type":"string","description":"UUID of the order that opened this lot, when it came from a Robinhood order. Absent for transfer, reward, or corporate-action lots."},"quantity":{"type":"string","description":"Shares in this lot. Negative for short-position lots."},"quantity_available":{"type":"string","description":"Shares in this lot not already earmarked by an open sell order (max(0, quantity - earmarked)). Use this for 'how much of this lot can I still sell?'."},"is_selectable":{"type":"boolean","description":"Whether this lot can be chosen in a specified-lot (lot selection) sell order. false for a lot that hasn't finished syncing yet — e.g. one acquired today (intraday) — which cannot be sold by lot selection until it does. Always present; not omitted when false, since false is the meaningful signal."},"cost_per_share":{"type":["null","string"],"description":"Tax cost basis per share (tax_cost_basis / quantity). Omitted when not yet available — e.g. a lot that hasn't finished syncing, missing cost basis, or zero quantity."},"tax_cost_basis":{"type":["null","string"],"description":"Total tax cost basis for the lot. Omitted when not yet available."},"open_date":{"type":"string","description":"Acquisition date (YYYY-MM-DD) that starts the holding period. Empty when unknown."},"term":{"type":"string","description":"Holding-period classification: 'lt' (long-term, held > 1 year) or 'st' (short-term). Other values ('or', 'mixed', 'lt-or', 'st-or', 'st40lt60', 'unknown') appear for special cases. Empty when not yet classified."}},"required":["open_lot_id","quantity","quantity_available","is_selectable"],"additionalProperties":false},"description":"Open tax lots for this holding on this page. Empty when the cursor has no rows or the holding has no open lots."},"next":{"type":"string","description":"Next-page URL. Empty when there are no more pages."}},"description":"Tool-specific result payload; see the inner properties for fields.","required":["symbol","tax_lots"],"additionalProperties":false},"guide":{"type":"string","description":"Lots are newest-acquired first by default. quantity is per-lot, not the whole position — sum quantity across lots for total shares, and quantity_available for total still-sellable shares. For which-lots-can-I-sell questions, only offer lots with is_selectable=true; a false value means the lot is still syncing (e.g. acquired today) and can't be picked for a specified-lot sell yet. Compare open_date to today to explain when a short-term lot crosses into long-term (term). When cost_per_share or tax_cost_basis is absent the basis is still pending — say so rather than treating it as zero. No live price here — for current value or unrealized gain/loss, call get_equity_quotes and combine with cost_per_share. Treat all figures as informational, not tax or performance advice. Page only when the user needs more than the first page."}},"required":["data","guide"],"additionalProperties":false},"annotations":{"readOnlyHint":true},"execution":null,"shape_hash":"sha256:b7db085b5c71b04e1b87d52605fb23623b48f5f32eeedcc696d126dc0a46596c","contract_hash":"sha256:1ecb07768c44c254b80fc7cd1d32cf055641385a8e24705b01f22ec74b7caa0e"},"category":null,"arguments":{},"result":{},"reason":"Tax lots have no matching callable category in this profile.","warnings":[],"original":{"name":"get_equity_tax_lots","category":null,"arguments":{},"result":{},"reason":"Tax lots have no matching callable category in this profile.","warnings":[]},"edits":[]},"get_equity_technical_indicators":{"contract":{"name":"get_equity_technical_indicators","title":null,"description":"Compute a technical indicator (RSI, MACD, Bollinger Bands, moving averages, ATR, VWAP, and more) over one equity symbol's OHLCV bars across a time range. For the raw OHLCV bars themselves, use get_equity_historicals.

Parameter rules:
- The parameters an indicator accepts depend on type:
  - period only: ema/sma (default 9); rsi/cci/atr/mfi (default 14); williams_r/adx (default 10); momentum (default 12); roc (default 14); donchian_channels (default 20).
  - bollinger_bands: period (default 20) + num_std (default 2).
  - macd: fast_period (12), slow_period (26), signal_period (9).
  - keltner_channels: period (default 20) + multiplier (default 2).
  - supertrend: period (default 10) + multiplier (default 3).
  - pivot_points: method (only 'classic').
  - vwap, obv: no parameters.
  Omit a parameter to use its default. Passing a parameter the chosen type does not accept is rejected.
- interval is REQUIRED — indicator periods are counted in bars, so there is no auto-selection.
- adjustment_type defaults to 'split'; 'all' (split + dividend) requires a day-or-coarser interval.
- If the requested range plus the indicator's warm-up exceeds the per-request bar cap, narrow the range or coarsen the interval.","input_schema":{"type":"object","properties":{"symbol":{"type":"string","description":"Stock symbol (uppercase). Exactly one symbol per call."},"type":{"type":"string","description":"Indicator to compute. One of: ema, sma, rsi, momentum, roc, cci, williams_r, atr, mfi, adx, donchian_channels, bollinger_bands, macd, keltner_channels, supertrend, vwap, obv, pivot_points."},"interval":{"type":"string","description":"Required bar interval the indicator is computed on. Intraday: 15second, 30second, minute, 5minute, 10minute, 30minute, hour, 4hour. Interday: day, week, month, 3month, 6month, year, 5year, 10year, 20year, 50year. The 1-minute bar is named 'minute' (not '1minute')."},"start_time":{"type":"string","description":"Start of the range (RFC3339 UTC, e.g. '2026-01-01T00:00:00Z'). Required."},"end_time":{"type":"string","description":"End of the range (RFC3339 UTC). Optional — defaults to the current time when omitted."},"bounds":{"type":"string","description":"Session bounds. One of 'regular' (RTH, default) or 'extended'."},"adjustment_type":{"type":"string","description":"Corporate-action adjustment: 'none' (raw prices), 'split' (default), or 'all' (split + dividend; requires a day-or-coarser interval)."},"output":{"type":"string","description":"How much of the series to return: 'series' (default, full range), 'latest' (most recent bar only), or 'last:N' (most recent N bars). The indicator is always computed over the full range first; this only trims the response."},"period":{"type":["null","integer"],"description":"Lookback period in bars. Applies to ema, sma, rsi, momentum, roc, cci, williams_r, atr, mfi, adx, donchian_channels, bollinger_bands, keltner_channels, supertrend. Omit to use the indicator's default."},"num_std":{"type":["null","number"],"description":"Number of standard deviations for the bands. bollinger_bands only (default 2)."},"fast_period":{"type":["null","integer"],"description":"Fast EMA period. macd only (default 12)."},"slow_period":{"type":["null","integer"],"description":"Slow EMA period. macd only (default 26)."},"signal_period":{"type":["null","integer"],"description":"Signal EMA period. macd only (default 9)."},"multiplier":{"type":["null","number"],"description":"Band/offset multiplier. keltner_channels (default 2) and supertrend (default 3) only."},"method":{"type":"string","description":"Calculation method. pivot_points only; currently only 'classic'."}},"required":["symbol","type","interval","start_time"],"additionalProperties":false},"output_schema":{"type":"object","properties":{"data":{"type":"object","properties":{"symbol":{"type":"string","description":"Ticker symbol echoed from the request."},"interval":{"type":"string","description":"Bar interval the indicator was computed on, echoed from the request."},"bounds":{"type":"string","description":"Session bounds echoed from the request."},"indicators":{"type":["null","array"],"items":{"type":["null","object"],"properties":{"type":{"type":"string","description":"Indicator type, e.g. 'rsi', 'macd', 'bollinger_bands'."},"params":{"type":"object","description":"Numeric parameters actually used after defaults were applied, e.g. {"period":14} or {"fast_period":12,"slow_period":26,"signal_period":9}.","additionalProperties":{"type":"number"}},"series":{"type":["null","array"],"items":{"type":["null","object"],"properties":{"begins_at":{"type":"string","description":"Bar start timestamp (RFC3339 UTC), left-edge labeled."}},"description":"One bar of indicator output: 'begins_at' plus one or more numeric output fields whose names depend on the indicator type — 'value' for single-output indicators; 'upper'/'middle'/'lower' for bollinger_bands and channel indicators; 'macd'/'signal'/'histogram' for macd. A field is null when the value is undefined for that bar."},"description":"Output bars in ascending time order, after the 