ially filled; equal once filled."},"price":{"type":["null","string"],"description":"Limit price for limit/stop_limit orders; null for market orders."},"stop_price":{"type":["null","string"],"description":"Stop trigger price for stop_market/stop_limit orders; null otherwise."},"average_price":{"type":["null","string"],"description":"Weighted average fill price across executions. Null until the first fill."},"fees":{"type":"string","description":"Cumulative fees (regulatory + clearing) in USD."},"dollar_based_amount":{"type":["null","object"],"properties":{"amount":{"type":"string","description":"Quoted-decimal amount, e.g. '100.00'."},"currency_code":{"type":"string","description":"ISO currency code; always 'USD' for equity orders today."}},"description":"Notional amount for dollar-based market orders; null for share-quantity orders.","required":["amount","currency_code"],"additionalProperties":false},"time_in_force":{"type":"string","description":"'gfd' (good for day) or 'gtc' (good till cancelled)."},"market_hours":{"type":"string","description":"'regular_hours', 'extended_hours', or 'all_day_hours'."},"trigger":{"type":"string","description":"'immediate' (market/limit) or 'stop' (stop_market/stop_limit)."},"placed_agent":{"type":"string","description":"Source that placed the order: 'user' (app), 'agentic' (MCP), 'recurring', 'drip', 'brokeback' (system), or other internal values."},"created_at":{"type":"string","description":"When the order was created."},"last_transaction_at":{"type":["null","string"],"description":"Time of the most recent fill, cancel, or reject. Null on a brand-new unfilled order."},"executions":{"type":["null","array"],"items":{"type":"object","properties":{"id":{"type":"string","description":"Execution UUID."},"price":{"type":"string","description":"Fill price per share."},"quantity":{"type":"string","description":"Shares filled in this execution."},"timestamp":{"type":"string","description":"When the fill occurred."},"fees":{"type":"string",